+nconf.defaults({ relative_path: '' });
+process.env.NODE_ENV = 'production';
+
+const redis = require('./src/database/redis');
+const connection = require('./src/database/redis/connection');
+
+async function run() {
+    await redis.init();
+    const client = redis.client;
+    
+    // First set a key
+    await client.async.hmset('testkey', { field1: 'value1', field2: 'value2' });
+    
+    // Test hgetall on existing key
+    const result1 = await client.async.hgetall('testkey');
+    console.log('hgetall existing:', result1);
+    console.log('Type:', typeof result1);
+    console.log('Keys:', Object.keys(result1));
+    
+    // Test hgetall on non-existent key
+    const result2 = await client.async.hgetall('nonexistent');
+    console.log('hgetall nonexistent:', result2);
+    console.log('Type:', typeof result2);
+    console.log('Keys:', Object.keys(result2));
+    console.log('Is empty object:', result2 && Object.keys(result2).length === 0);
+    
+    // Test batch hgetall
+    const batch = client.batch();
+    batch.hgetall('testkey');
+    batch.hgetall('nonexistent');
