+		const nextPid = await db.getObjectField('global', 'nextPid');
+		const pids = [];
+		for (let x = 1; x < nextPid; x++) {
+			pids.push(x);
+		}
+
+		// Filter to only existing posts
+		const existingPids = (await db.isSortedSetMembers('posts:pid', pids))
+			.map((exists, idx) => (exists ? pids[idx] : false))
+			.filter(Boolean);
+
+		progress.total = existingPids.length;
+
+		// Process posts in batches
+		await batch.processArray(existingPids, async (pids) => {
+			await Promise.all(pids.map(async (pid) => {
+				// Get current uploads (without files/ prefix)
+				const currentUploads = await db.getSortedSetMembers(`post:${pid}:uploads`);
+
+				if (!currentUploads.length) {
+					progress.incr();
+					return;
+				}
+
+				// Add "files/" prefix to each path
+				const normalizedUploads = currentUploads.map(upload => `files/${upload}`);
+
+				// Build bulk operations to migrate data
+				const bulkAdd = [];
+				const bulkRemove = [];
+
+				// Add new entries with files/ prefix
+				const now = Date.now();
+				const scores = normalizedUploads.map(() => now);
+				for (let i = 0; i < normalizedUploads.length; i++) {
+					const newPath = normalizedUploads[i];
+					const oldPath = currentUploads[i];
+					bulkAdd.push([`upload:${md5(newPath)}:pids`, now, pid]);
+					bulkRemove.push([`upload:${md5(oldPath)}:pids`, pid]);
+				}
+
+				// Perform the migration
+				const promises = [
+					db.sortedSetAdd(`post:${pid}:uploads`, scores, normalizedUploads),
+					db.sortedSetAddBulk(bulkAdd),
+				];
+
+				// Remove old entries
+				if (bulkRemove.length) {
+					promises.push(db.sortedSetRemoveBulk(bulkRemove));
+				}
+
+				// Also remove old sorted set keys if they exist
+				for (const oldPath of currentUploads) {
+					promises.push(db.delete(`upload:${md5(oldPath)}:pids`));
+				}
+
+				await Promise.all(promises);
+				progress.incr();
+			}));
+		}, {
+			progress,
+			batch: 100,
+		});
+	},
+};
