+<!DOCTYPE html>
+<html>
+<head>
+    <title>Markdown URL Test</title>
+</head>
+<body>
+    <h1>Markdown URL Test</h1>
+    <div id="output"></div>
+    <script type="module">
+        import Markdown from '/app/src/Markdown.ts';
+        
+        const testCases = [
+            {
+                name: "URL with underscores in emphasis",
+                input: "_https://example.com/_test_test2_-test3_",
+                description: "URL with underscores inside emphasized text"
+            },
+            {
+                name: "URL with double underscores in strong",
+                input: "__https://example.com/_test__test2__test3__",
+                description: "URL with mixed underscores inside strong text"
+            },
+            {
+                name: "Plain URL with underscores",
+                input: "https://example.com/_test__test2__test3_",
+                description: "Plain autolink with underscores"
+            },
+            {
+                name: "Multiline link",
+                input: "https://example.com/\n_test_test2_",
+                description: "Multiline link with underscores"
+            }
+        ];
+        
+        const output = document.getElementById('output');
+        
+        testCases.forEach(tc => {
+            const md = new Markdown(tc.input);
+            const html = md.toHTML();
+            
+            const testDiv = document.createElement('div');
+            testDiv.style.marginBottom = '20px';
+            testDiv.innerHTML = `
+                <h3>${tc.name}</h3>
+                <p><strong>Input:</strong> <code>${tc.input}</code></p>
+                <p><strong>Description:</strong> ${tc.description}</p>
+                <p><strong>HTML Output:</strong> <code>${html.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</code></p>
+                <p><strong>Rendered:</strong> <span>${html}</span></p>
+            `;
+            output.appendChild(testDiv);
+        });
+    </script>
+</body>
+</html>

