+
+/**
+ * Represents a keyboard shortcut as a combination of a key and optional modifier flags.
+ * @typedef {Object} KeyCombo
+ * @property {string} key - The key to match (e.g., "a", "Enter", "Escape").
+ * @property {boolean} [ctrlKey] - Whether Control must be pressed.
+ * @property {boolean} [altKey] - Whether Alt must be pressed.
+ * @property {boolean} [shiftKey] - Whether Shift must be pressed.
+ * @property {boolean} [metaKey] - Whether Meta/Command must be pressed.
+ * @property {boolean} [ctrlOrCmd] - Whether Control (on non-macOS) or Command (on macOS) must be pressed.
+ */
+export interface KeyCombo {
+    key: string;
+    ctrlKey?: boolean;
+    altKey?: boolean;
+    shiftKey?: boolean;
+    metaKey?: boolean;
+    ctrlOrCmd?: boolean;
+}
+
+/**
+ * Checks whether a given KeyboardEvent matches a KeyCombo.
+ * 
+ * The function returns true only when the pressed key and modifiers exactly match
+ * the combination, and false when extra modifiers are present. On macOS, ctrlOrCmd
+ * is interpreted as Command; on other platforms, it's interpreted as Control.
+ * 
+ * Letter keys are matched consistently regardless of capitalization, and Shift is
+ * properly accounted for without breaking the match.
+ * 
+ * @param {KeyboardEvent | React.KeyboardEvent} ev - The keyboard event to check.
+ * @param {KeyCombo} combo - The key combination to match against.
+ * @param {boolean} [onMac] - Whether we're running on macOS. Defaults to checking navigator.platform.
+ * @returns {boolean} True if the event matches the combination, false otherwise.
+ */
+export function isKeyComboMatch(
+    ev: KeyboardEvent | React.KeyboardEvent,
+    combo: KeyCombo,
+    onMac?: boolean,
+): boolean {
+    // Determine if we're on macOS
+    const isMacPlatform = onMac ?? (typeof navigator !== 'undefined' && navigator.platform.toUpperCase().indexOf('MAC') >= 0);
+
+    // Normalize the event key to lowercase for letter comparison
+    const eventKey = normalizeKey(ev.key);
+    const comboKey = normalizeKey(combo.key);
+
+    // Check that the key matches
+    if (eventKey !== comboKey) {
+        return false;
+    }
+
+    // Determine which modifier keys should be pressed
+    let expectedCtrl = combo.ctrlKey || false;
+    let expectedAlt = combo.altKey || false;
+    let expectedShift = combo.shiftKey || false;
+    let expectedMeta = combo.metaKey || false;
+
+    // Handle ctrlOrCmd: on macOS this is Command, otherwise it's Control
+    if (combo.ctrlOrCmd) {
+        if (isMacPlatform) {
+            expectedMeta = true;
+        } else {
+            expectedCtrl = true;
+        }
+    }
+
+    // Check that all required modifiers are present
+    if (ev.ctrlKey !== expectedCtrl) {
+        return false;
+    }
+    if (ev.altKey !== expectedAlt) {
+        return false;
+    }
+    if (ev.shiftKey !== expectedShift) {
+        return false;
+    }
+    if (ev.metaKey !== expectedMeta) {
+        return false;
+    }
+
+    // Ensure no extra modifiers are pressed
+    // Count how many modifiers are actually pressed
+    const actualModifiers = [ev.ctrlKey, ev.altKey, ev.shiftKey, ev.metaKey].filter(Boolean).length;
+    const expectedModifiers = [expectedCtrl, expectedAlt, expectedShift, expectedMeta].filter(Boolean).length;
+
+    if (actualModifiers !== expectedModifiers) {
+        return false;
+    }
+
+    return true;
+}
+
+/**
+ * Normalizes a key from a KeyboardEvent to a consistent format.
+ * Handles capitalization by converting to lowercase for letter keys.
+ * @param {string} key - The key value from the event.
+ * @returns {string} The normalized key.
+ */
+function normalizeKey(key: string): string {
+    // For letter keys, normalize to lowercase so "A" and "a" match the same combo
+    if (key.length === 1 && key.toUpperCase() !== key.toLowerCase()) {
+        return key.toLowerCase();
+    }
+    return key;
+}

