+import React, { useState, useCallback } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Field from '../../elements/Field';
+import Spinner from '../../elements/Spinner';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+const DeviceDetailHeading: React.FC<Props> = ({
+    device,
+    saveDeviceName,
+}) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [editingName, setEditingName] = useState(device.display_name || '');
+    const [isSaving, setIsSaving] = useState(false);
+    const [saveError, setSaveError] = useState<string | null>(null);
+
+    const handleRenameClick = useCallback(() => {
+        setSaveError(null);
+        setEditingName(device.display_name || '');
+        setIsEditing(true);
+    }, [device.display_name]);
+
+    const handleNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
+        setSaveError(null);
+        setEditingName(e.target.value);
+    }, []);
+
+    const handleSave = useCallback(async (e: React.FormEvent) => {
+        e.preventDefault();
+        
+        if (editingName === device.display_name) {
+            setIsEditing(false);
+            return;
+        }
+
+        setIsSaving(true);
+        setSaveError(null);
+
+        try {
+            await saveDeviceName(device.device_id, editingName);
+            setIsEditing(false);
+            setIsSaving(false);
+        } catch (error) {
+            setSaveError(_t('Failed to set display name.'));
+            setIsSaving(false);
+        }
+    }, [editingName, device.device_id, device.display_name, saveDeviceName]);
+
+    const handleCancel = useCallback(() => {
+        setSaveError(null);
+        setEditingName(device.display_name || '');
+        setIsEditing(false);
+    }, [device.display_name]);
+
+    // When editing name is empty, use device_id as fallback for display
+    const displayName = isEditing ? editingName : (device.display_name || device.device_id);
+
+    if (isEditing) {
+        return (
+            <form
+                className="mx_DeviceDetailHeading_editForm"
+                onSubmit={handleSave}
+                data-testid="device-detail-heading-edit-form"
+            >
+                <div className="mx_DeviceDetailHeading_editInputContainer">
+                    <Field
+                        id={`device-name-input-${device.device_id}`}
+                        type="text"
+                        value={editingName}
+                        onChange={handleNameChange}
+                        placeholder={device.device_id}
+                        className="mx_DeviceDetailHeading_input"
+                        data-testid="device-name-input"
+                        autoFocus={true}
+                    />
+                </div>
+                <div className="mx_DeviceDetailHeading_saveControls">
+                    <AccessibleButton
+                        kind="primary_sm"
+                        type="submit"
+                        disabled={isSaving}
+                        onClick={handleSave}
+                        data-testid="device-name-save-btn"
+                    >
+                        {isSaving ? <Spinner w={16} h={16} /> : _t('Save')}
+                    </AccessibleButton>
+                    <AccessibleButton
+                        kind="link_sm"
+                        onClick={handleCancel}
+                        data-testid="device-name-cancel-btn"
+                    >
+                        {_t('Cancel')}
+                    </AccessibleButton>
+                </div>
+                {saveError && (
+                    <div
+                        className="mx_DeviceDetailHeading_error"
+                        data-testid="device-name-error"
+                    >
+                        {saveError}
+                    </div>
+                )}
+                <div
+                    className="mx_DeviceDetailHeading_visibilityNotice"
+                    data-testid="device-visibility-notice"
+                >
+                    {_t('Session names may be visible to other people you communicate with.')}
+                </div>
+            </form>
+        );
+    }
+
+    return (
+        <div
+            className="mx_DeviceDetailHeading"
+            data-testid="device-detail-heading"
+        >
+            <h3 className="mx_DeviceDetailHeading_name">
+                {displayName}
+            </h3>
+            <AccessibleButton
+                kind="link_inline"
+                onClick={handleRenameClick}
+                data-testid="device-rename-btn"
+            >
+                {_t('Rename')}
+            </AccessibleButton>
+        </div>
+    );
+};
+
+export default DeviceDetailHeading;
