diff --git a/src/components/views/rooms/EventPreview.tsx b/src/components/views/rooms/EventPreview.tsx
new file mode 100644
index 0000000000..07afc98960
--- /dev/null
+++ b/src/components/views/rooms/EventPreview.tsx
@@ -0,0 +1,210 @@
+/*
+ * Copyright 2024 New Vector Ltd.
+ * Copyright 2024 The Matrix.org Foundation C.I.C.
+ *
+ * SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+ * Please see LICENSE files in the repository root for full details.
+ */
+
+import React, { JSX, useEffect, useState } from "react";
+import {
+    MatrixEvent,
+    MatrixEventEvent,
+    M_POLL_START,
+    MsgType,
+    ThreadEvent,
+} from "matrix-js-sdk/src/matrix";
+import { useAsyncMemo } from "../../../hooks/useAsyncMemo";
+import { _t } from "../../../languageHandler";
+import { MessagePreviewStore } from "../../../stores/room-list/MessagePreviewStore";
+
+/**
+ * A tuple representing the preview text and optional prefix.
+ */
+type Preview = [preview: string, prefix: string | null];
+
+/**
+ * The props for the {@link EventPreview} component.
+ */
+interface EventPreviewProps extends React.HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The MatrixEvent to generate the preview for.
+     */
+    mxEvent: MatrixEvent;
+    /**
+     * Optional CSS class names to add to the component.
+     */
+    className?: string;
+}
+
+/**
+ * The props for the {@link EventPreviewTile} component.
+ */
+interface EventPreviewTileProps extends React.HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The preview tuple containing the preview text and optional prefix.
+     */
+    preview: Preview;
+    /**
+     * Optional CSS class names to add to the component.
+     */
+    className?: string;
+}
+
+/**
+ * A React hook that generates a preview string and optional message type prefix
+ * for a given MatrixEvent.
+ * @param mxEvent - The MatrixEvent to generate the preview for.
+ * @returns A tuple [previewText, prefix] or null if no preview can be generated.
+ */
+export function useEventPreview(mxEvent?: MatrixEvent): Preview | null {
+    const [previewAndPrefix, setPreviewAndPrefix] = useState<Preview | null>(null);
+
+    // Track content to regenerate preview on edits
+    const [content, setContent] = useState<Record<string, unknown> | undefined>(mxEvent?.getContent());
+
+    // Track decryption state
+    const [decryptedContent, setDecryptedContent] = useState<Record<string, unknown> | undefined>(
+        mxEvent?.isDecrypted() ? mxEvent?.getContent() : undefined,
+    );
+
+    // Update content when event is replaced (edits)
+    useEffect(() => {
+        if (!mxEvent) return;
+        const onReplaced = (): void => {
+            setContent(mxEvent.getContent());
+        };
+        mxEvent.on(MatrixEventEvent.Replaced, onReplaced);
+        return () => {
+            mxEvent.off(MatrixEventEvent.Replaced, onReplaced);
+        };
+    }, [mxEvent]);
+
+    // Update content when event is decrypted
+    useEffect(() => {
+        if (!mxEvent) return;
+        const onDecrypted = (): void => {
+            setDecryptedContent(mxEvent.getContent());
+        };
+        mxEvent.on(MatrixEventEvent.Decrypted, onDecrypted);
+        return () => {
+            mxEvent.off(MatrixEventEvent.Decrypted, onDecrypted);
+        };
+    }, [mxEvent]);
+
+    // Update content when thread event updates
+    useEffect(() => {
+        if (!mxEvent?.getThread()) return;
+        const onThreadUpdate = (): void => {
+            setContent(mxEvent.getContent());
+        };
+        mxEvent.getThread()!.on(ThreadEvent.Update, onThreadUpdate);
+        return () => {
+            mxEvent.getThread()!.off(ThreadEvent.Update, onThreadUpdate);
+        };
+    }, [mxEvent]);
+
+    // Generate preview using async memo to defer expensive operations
+    const generatedPreview = useAsyncMemo(async (): Promise<string | null> => {
+        if (!mxEvent || mxEvent.isRedacted() || mxEvent.isDecryptionFailure()) {
+            return null;
+        }
+
+        // Wait for decryption if needed
+        if (mxEvent.shouldAttemptDecryption() || mxEvent.isBeingDecrypted()) {
+            await mxEvent.getClient().decryptEventIfNeeded(mxEvent);
+        }
+
+        return MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+    }, [mxEvent, content, decryptedContent]);
+
+    // Generate prefix based on event type
+    const prefix = generatePreviewPrefix(mxEvent);
+
+    // Update state when preview is generated
+    useEffect(() => {
+        if (generatedPreview === null || generatedPreview === undefined) {
+            setPreviewAndPrefix(null);
+        } else {
+            setPreviewAndPrefix([generatedPreview, prefix]);
+        }
+    }, [generatedPreview, prefix]);
+
+    return previewAndPrefix;
+}
+
+/**
+ * Generates the prefix for a message based on its type.
+ * @param mxEvent - The MatrixEvent to generate the prefix for.
+ * @returns The prefix string or null if no prefix should be shown.
+ */
+function generatePreviewPrefix(mxEvent?: MatrixEvent): string | null {
+    if (!mxEvent) return null;
+
+    const type = mxEvent.getType();
+    const content = mxEvent.getContent();
+    const msgType = content?.msgtype as MsgType;
+
+    // Polls
+    if (type === M_POLL_START.name || type === M_POLL_START.altName) {
+        return _t("event_preview|prefix|poll");
+    }
+
+    // Media types
+    switch (msgType) {
+        case MsgType.Image:
+            return _t("event_preview|prefix|image");
+        case MsgType.Video:
+            return _t("event_preview|prefix|video");
+        case MsgType.Audio:
+            return _t("event_preview|prefix|audio");
+        case MsgType.File:
+            return _t("event_preview|prefix|file");
+        default:
+            return null;
+    }
+}
+
+/**
+ * A React component that displays a preview for a MatrixEvent with an optional
+ * type prefix (e.g., "Image:", "Audio:", "Poll:").
+ * @param props - The component props.
+ * @returns The rendered component or null if no preview is available.
+ */
+export function EventPreview({ mxEvent, className, ...props }: EventPreviewProps): JSX.Element | null {
+    const preview = useEventPreview(mxEvent);
+    if (!preview) return null;
+
+    return <EventPreviewTile preview={preview} className={className} {...props} />;
+}
+
+/**
+ * A React component that renders a preview string along with an optional prefix
+ * in a styled span.
+ * @param props - The component props.
+ * @returns The rendered React element or null.
+ */
+export function EventPreviewTile({ preview, className, ...props }: EventPreviewTileProps): JSX.Element | null {
+    const [previewText, prefix] = preview;
+
+    if (!prefix) {
+        return (
+            <span className={className} {...props}>
+                {previewText}
+            </span>
+        );
+    }
+
+    return (
+        <span className={className} {...props}>
+            {_t("event_preview|prefix_format", {
+                prefix: (
+                    <span className="mx_EventPreview_prefix">
+                        {prefix}
+                    </span>
+                ),
+                preview: previewText,
+            })}
+        </span>
+    );
+}
