+
+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+import { MatrixClient } from "matrix-js-sdk/src/client";
+import { MatrixEvent } from "matrix-js-sdk/src/models/event";
+import { RelationType } from "matrix-js-sdk/src/matrix";
+import { logger } from "matrix-js-sdk/src/logger";
+
+import {
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+    VoiceBroadcastInfoEventContent,
+} from "..";
+
+/**
+ * Events emitted by VoiceBroadcastRecording.
+ */
+export enum VoiceBroadcastRecordingEvent {
+    /**
+     * Emitted when the broadcast recording state changes.
+     */
+    StateChanged = "state_changed",
+}
+
+/**
+ * Event handler map for VoiceBroadcastRecording events.
+ */
+export interface VoiceBroadcastRecordingEventHandlerMap {
+    [VoiceBroadcastRecordingEvent.StateChanged]: (
+        newState: VoiceBroadcastInfoState,
+        prevState: VoiceBroadcastInfoState,
+    ) => void;
+}
+
+/**
+ * Represents a single voice broadcast recording, managing its state, sending stop events,
+ * and emitting state change notifications.
+ */
+export class VoiceBroadcastRecording extends TypedEventEmitter<VoiceBroadcastRecordingEvent, VoiceBroadcastRecordingEventHandlerMap> {
+    /**
+     * The Matrix client instance.
+     */
+    private readonly client: MatrixClient;
+
+    /**
+     * The info event that represents this voice broadcast.
+     */
+    private readonly infoEvent: MatrixEvent;
+
+    /**
+     * The current state of the broadcast recording.
+     */
+    private _state: VoiceBroadcastInfoState;
+
+    /**
+     * Creates a new VoiceBroadcastRecording instance.
+     * @param client - The Matrix client instance.
+     * @param infoEvent - The info event that represents this voice broadcast.
+     * @param state - The initial state of the broadcast.
+     */
+    public constructor(client: MatrixClient, infoEvent: MatrixEvent, state: VoiceBroadcastInfoState) {
+        super();
+        this.client = client;
+        this.infoEvent = infoEvent;
+        this._state = state;
+    }
+
+    /**
+     * The room ID where the broadcast is happening.
+     * @returns The room ID.
+     */
+    public getRoomId(): string {
+        return this.infoEvent.getRoomId();
+    }
+
+    /**
+     * The ID of the info event.
+     * @returns The event ID.
+     */
+    public getId(): string {
+        return this.infoEvent.getId();
+    }
+
+    /**
+     * The current state of the broadcast recording.
+     * @returns The current state.
+     */
+    public get state(): VoiceBroadcastInfoState {
+        return this._state;
+    }
+
+    /**
+     * Stops the voice broadcast by sending a stopped state event to the room.
+     * The broadcast info event must have been sent to the room already.
+     * @returns A promise that resolves when the stop event has been sent.
+     */
+    public async stop(): Promise<void> {
+        const roomId = this.getRoomId();
+        const userId = this.client.getUserId();
+
+        if (!roomId || !userId) {
+            logger.error("VoiceBroadcastRecording.stop: missing room ID or user ID");
+            return;
+        }
+
+        const newContent: VoiceBroadcastInfoEventContent = {
+            state: VoiceBroadcastInfoState.Stopped,
+            chunk_length: this.infoEvent.getContent<VoiceBroadcastInfoEventContent>()?.chunk_length ?? 60000,
+            ["m.relates_to"]: {
+                rel_type: RelationType.Reference,
+                event_id: this.infoEvent.getId(),
+            },
+        };
+
+        await this.client.sendStateEvent(roomId, VoiceBroadcastInfoEventType, newContent, userId);
+
+        // Update local state
+        this._state = VoiceBroadcastInfoState.Stopped;
+        this.emit(VoiceBroadcastRecordingEvent.StateChanged, VoiceBroadcastInfoState.Stopped, VoiceBroadcastInfoState.Started);
+    }
+
+    /**
+     * Updates the state of the broadcast recording.
+     * @param newState - The new state.
+     * @param prevState - The previous state.
+     */
+    public setState(newState: VoiceBroadcastInfoState, prevState: VoiceBroadcastInfoState): void {
+        if (this._state !== newState) {
+            const oldState = this._state;
+            this._state = newState;
+            this.emit(VoiceBroadcastRecordingEvent.StateChanged, newState, oldState);
+        }
+    }
+}
