+
+/**
+ * Events emitted by VoiceBroadcastRecordingsStore.
+ */
+export enum VoiceBroadcastRecordingsStoreEvent {
+    /**
+     * Emitted when the current recording changes.
+     */
+    CurrentChanged = "current_changed",
+}
+
+/**
+ * Event handler map for VoiceBroadcastRecordingsStore events.
+ */
+export interface VoiceBroadcastRecordingsStoreEventHandlerMap {
+    [VoiceBroadcastRecordingsStoreEvent.CurrentChanged]: (recording: VoiceBroadcastRecording | null) => void;
+}
+
+/**
+ * Singleton store for caching and tracking voice broadcast recordings by info event ID,
+ * exposes the current recording and emits events on change.
+ */
+export class VoiceBroadcastRecordingsStore extends TypedEventEmitter<VoiceBroadcastRecordingsStoreEvent, VoiceBroadcastRecordingsStoreEventHandlerMap> {
+    /**
+     * The singleton instance of the store.
+     */
+    public static instance: VoiceBroadcastRecordingsStore;
+
+    /**
+     * A map of recordings by info event ID.
+     */
+    private recordings = new Map<string, VoiceBroadcastRecording>();
+
+    /**
+     * The current recording being tracked by the store.
+     */
+    private _current: VoiceBroadcastRecording | null = null;
+
+    /**
+     * Private constructor to enforce singleton pattern.
+     */
+    private constructor() {
+        super();
+    }
+
+    /**
+     * Returns the current recording being tracked by the store.
+     * @returns The current recording, or null if none is active.
+     */
+    public get current(): VoiceBroadcastRecording | null {
+        return this._current;
+    }
+
+    /**
+     * Sets the current recording in the store and emits a CurrentChanged event.
+     * @param current - The new current recording, or null to clear it.
+     */
+    public setCurrent(current: VoiceBroadcastRecording | null): void {
+        if (this._current !== current) {
+            const oldCurrent = this._current;
+            this._current = current;
+            logger.debug(`VoiceBroadcastRecordingsStore: current recording changed from ${oldCurrent?.getId() || "null"} to ${current?.getId() || "null"}`);
+            this.emit(VoiceBroadcastRecordingsStoreEvent.CurrentChanged, current);
+        }
+    }
+
+    /**
+     * Returns the cached recording for the given info event, or null if none exists.
+     * @param infoEvent - The info event to look up.
+     * @returns The cached recording, or null if not found.
+     */
+    public getByInfoEvent(infoEvent: MatrixEvent): VoiceBroadcastRecording | null {
+        const eventId = infoEvent.getId();
+        return eventId ? this.recordings.get(eventId) || null : null;
+    }
+
+    /**
+     * Returns the cached recording for the given info event, or creates a new one if not present.
+     * @param client - The Matrix client instance.
+     * @param infoEvent - The info event to look up or create from.
+     * @param state - The initial state for a new recording.
+     * @returns The recording for the given info event.
+     */
+    public getOrCreateRecording(client: MatrixClient, infoEvent: MatrixEvent, state: VoiceBroadcastRecording["state"]): VoiceBroadcastRecording {
+        const eventId = infoEvent.getId();
+        if (!eventId) {
+            throw new Error("Cannot create recording for info event without ID");
+        }
+
+        let recording = this.recordings.get(eventId);
+        if (!recording) {
+            recording = new VoiceBroadcastRecording(client, infoEvent, state);
+            this.recordings.set(eventId, recording);
+
+            // Listen for state changes and update the recording's state
+            recording.on(VoiceBroadcastRecordingEvent.StateChanged, (newState) => {
+                logger.debug(`VoiceBroadcastRecording ${eventId} state changed to ${newState}`);
+            });
+        }
+
+        return recording;
+    }
+
+    /**
+     * Removes a recording from the cache.
+     * @param infoEvent - The info event whose recording should be removed.
+     */
+    public removeRecording(infoEvent: MatrixEvent): void {
+        const eventId = infoEvent.getId();
+        if (eventId) {
+            this.recordings.delete(eventId);
+            if (this._current?.getId() === eventId) {
+                this.setCurrent(null);
+            }
+        }
+    }
+
+    /**
+     * Starts tracking a new recording and sets it as the current one.
+     * @param recording - The recording to track.
+     */
+    public startRecording(recording: VoiceBroadcastRecording): void {
+        this.recordings.set(recording.getId(), recording);
+        this.setCurrent(recording);
+    }
+}
