+	// Invalidate evaluation rules cache on rule creation
+	rule, err := s.Store.CreateRule(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	// Delete evaluation rules cache for this flag
+	cacheKey := fmt.Sprintf(evaluationRulesCacheKeyFmt, rule.NamespaceKey, rule.FlagKey)
+	s.deleteFromCache(ctx, cacheKey)
