+func TestCheckerTokenSupport(t *testing.T) {
+	testCases := []struct {
+		name          string
+		eventPairs    []string
+		expectedError error
+		pairs         map[string]bool
+	}{
+		{
+			name:          "token:created event",
+			eventPairs:    []string{"token:created"},
+			expectedError: nil,
+			pairs: map[string]bool{
+				"token:created":  true,
+				"token:deleted":  false,
+				"token:updated":  false,
+				"flag:created":   false,
+			},
+		},
+		{
+			name:          "token:deleted event",
+			eventPairs:    []string{"token:deleted"},
+			expectedError: nil,
+			pairs: map[string]bool{
+				"token:created":  false,
+				"token:deleted":  true,
+				"token:updated":  false,
+			},
+		},
+		{
+			name:          "wild card for nouns includes token",
+			eventPairs:    []string{"*:created"},
+			expectedError: nil,
+			pairs: map[string]bool{
+				"token:created":  true,
+				"flag:created":   true,
+				"token:deleted":  false,
+			},
+		},
+		{
+			name:          "wild card for verbs with token",
+			eventPairs:    []string{"token:*"},
+			expectedError: nil,
+			pairs: map[string]bool{
+				"token:created": true,
+				"token:deleted": true,
+				"token:updated": true,
+				"flag:created":  false,
+			},
+		},
+		{
+			name:          "wild card noun includes all token events",
+			eventPairs:    []string{"*:*"},
+			expectedError: nil,
+			pairs: map[string]bool{
+				"token:created":  true,
+				"token:deleted":  true,
+				"token:updated":  true,
+				"flag:created":   true,
+				"flag:deleted":   true,
+			},
+		},
+	}
+
+	for _, tc := range testCases {
+		t.Run(tc.name, func(t *testing.T) {
+			checker, err := NewChecker(tc.eventPairs)
+			if tc.expectedError != nil {
+				assert.EqualError(t, err, tc.expectedError.Error())
+				return
+			}
+			assert.NoError(t, err)
+
+			for k, v := range tc.pairs {
+				actual := checker.Check(k)
+				assert.Equal(t, v, actual, "event pair %s", k)
+			}
+		})
+	}
+}
