+func TestAuditUnaryInterceptor_DeleteToken(t *testing.T) {
+	var (
+		logger      = zaptest.NewLogger(t)
+		exporterSpy = newAuditExporterSpy(logger)
+		req         = &authrpc.DeleteAuthenticationRequest{
+			Id: "auth-id",
+		}
+	)
+
+	unaryInterceptor := AuditUnaryInterceptor(logger, &checkerDummyTokenDeleted{})
