+// TestExportSortByKey tests that sorting is enabled when sortByKey is true
+func TestExportSortByKey(t *testing.T) {
+	tests := []struct {
+		name          string
+		lister        mockLister
+		allNamespaces bool
+		expectedKeys  []string // Expected order of namespace/flag/segment keys
+	}{
+		{
+			name: "all namespaces sorted by key",
+			lister: mockLister{
+				namespaces: map[string]*flipt.Namespace{
+					"0_zoo": {
+						Key:         "zoo",
+						Name:        "zoo",
+						Description: "zoo namespace",
+					},
+					"1_alpha": {
+						Key:         "alpha",
+						Name:        "alpha",
+						Description: "alpha namespace",
+					},
+					"2_beta": {
+						Key:         "beta",
+						Name:        "beta",
+						Description: "beta namespace",
+					},
+				},
+				nsToFlags: map[string][]*flipt.Flag{
+					"zoo":  {},
+					"alpha": {},
+					"beta":  {},
+				},
+				nsToSegments: map[string][]*flipt.Segment{
+					"zoo":  {},
+					"alpha": {},
+					"beta":  {},
+				},
+				nsToRules:    map[string][]*flipt.Rule{},
+				nsToRollouts: map[string][]*flipt.Rollout{},
+			},
+			allNamespaces: true,
+			expectedKeys:  []string{"alpha", "beta", "zoo"},
+		},
+		{
+			name: "single namespace with flags sorted by key",
+			lister: mockLister{
+				namespaces: map[string]*flipt.Namespace{
+					"0_default": {
+						Key:         "default",
+						Name:        "default",
+						Description: "default namespace",
+					},
+				},
+				nsToFlags: map[string][]*flipt.Flag{
+					"default": {
+						{
+							Key:         "zebra",
+							Name:        "zebra",
+							Type:        flipt.FlagType_VARIANT_FLAG_TYPE,
+							Description: "zebra flag",
+							Enabled:     true,
+							Variants:    []*flipt.Variant{{Id: "1", Key: "variant1"}},
+						},
+						{
+							Key:         "apple",
+							Name:        "apple",
+							Type:        flipt.FlagType_VARIANT_FLAG_TYPE,
+							Description: "apple flag",
+							Enabled:     true,
+							Variants:    []*flipt.Variant{{Id: "2", Key: "variant2"}},
+						},
+						{
+							Key:         "mango",
+							Name:        "mango",
+							Type:        flipt.FlagType_VARIANT_FLAG_TYPE,
+							Description: "mango flag",
+							Enabled:     true,
+							Variants:    []*flipt.Variant{{Id: "3", Key: "variant3"}},
+						},
+					},
+				},
+				nsToSegments: map[string][]*flipt.Segment{
+					"default": {},
+				},
+				nsToRules:    map[string][]*flipt.Rule{},
+				nsToRollouts: map[string][]*flipt.Rollout{},
+			},
+			allNamespaces: false,
+			expectedKeys:  []string{"apple", "mango", "zebra"},
+		},
+		{
+			name: "single namespace with segments sorted by key",
+			lister: mockLister{
+				namespaces: map[string]*flipt.Namespace{
+					"0_default": {
+						Key:         "default",
+						Name:        "default",
+						Description: "default namespace",
+					},
+				},
+				nsToFlags: map[string][]*flipt.Flag{
+					"default": {},
+				},
+				nsToSegments: map[string][]*flipt.Segment{
+					"default": {
+						{
+							Key:         "segmentZ",
+							Name:        "segmentZ",
+							Description: "segment Z",
+							MatchType:   flipt.MatchType_ANY_MATCH_TYPE,
+						},
+						{
+							Key:         "segmentA",
+							Name:        "segmentA",
+							Description: "segment A",
+							MatchType:   flipt.MatchType_ANY_MATCH_TYPE,
+						},
+						{
+							Key:         "segmentM",
+							Name:        "segmentM",
+							Description: "segment M",
+							MatchType:   flipt.MatchType_ANY_MATCH_TYPE,
+						},
+					},
+				},
+				nsToRules:    map[string][]*flipt.Rule{},
+				nsToRollouts: map[string][]*flipt.Rollout{},
+			},
+			allNamespaces: false,
+			expectedKeys:  []string{"segmentA", "segmentM", "segmentZ"},
+		},
+		{
+			name: "flags with variants sorted by key",
+			lister: mockLister{
+				namespaces: map[string]*flipt.Namespace{
+					"0_default": {
+						Key:         "default",
+						Name:        "default",
+						Description: "default namespace",
+					},
+				},
+				nsToFlags: map[string][]*flipt.Flag{
+					"default": {
+						{
+							Key:         "flag1",
+							Name:        "flag1",
+							Type:        flipt.FlagType_VARIANT_FLAG_TYPE,
+							Description: "flag1",
+							Enabled:     true,
+							Variants: []*flipt.Variant{
+								{Id: "3", Key: "zoo"},
+								{Id: "1", Key: "apple"},
+								{Id: "2", Key: "mango"},
+							},
+						},
+					},
+				},
+				nsToSegments: map[string][]*flipt.Segment{
+					"default": {},
+				},
+				nsToRules:    map[string][]*flipt.Rule{},
+				nsToRollouts: map[string][]*flipt.Rollout{},
+			},
+			allNamespaces: false,
+			expectedKeys:  []string{"apple", "mango", "zoo"},
+		},
+	}
+
+	for _, tc := range tests {
+		tc := tc
+		for _, ext := range extensions {
+			t.Run(fmt.Sprintf("%s sorted (%s)", tc.name, ext), func(t *testing.T) {
+				exporter := NewExporter(tc.lister, "default", tc.allNamespaces, true)
+				b := new(bytes.Buffer)
+
+				err := exporter.Export(context.Background(), ext, b)
+				require.NoError(t, err)
+
+				// Decode the output and verify order
+				decoder := ext.NewDecoder(b)
+
+				// For YAML/JSON, we expect an array of documents
+				// We'll read the document and check the order
+				var doc Document
+				err = decoder.Decode(&doc)
+				require.NoError(t, err)
+
+				if tc.allNamespaces {
+					// Verify namespace order
+					if doc.Namespace != nil {
+						// For multi-namespace exports, we need to check the namespace order
+						// by reading all documents
+						b.Seek(0, 0)
+						decoder = ext.NewDecoder(b)
+
+						keys := []string{}
+						for {
+							var d Document
+							err := decoder.Decode(&d)
+							if errors.Is(err, io.EOF) {
+								break
+							}
+							require.NoError(t, err)
+							if d.Namespace != nil {
+								keys = append(keys, d.Namespace.GetKey())
+							}
+						}
+
+						assert.Equal(t, tc.expectedKeys, keys, "namespace order should be sorted")
+					}
+				} else {
+					// For single namespace, verify flag/segment order
+					if len(tc.expectedKeys) > 0 {
+						// Check flags
+						if len(doc.Flags) > 0 && len(doc.Flags[0].Variants) > 0 {
+							keys := []string{}
+							for _, f := range doc.Flags {
+								keys = append(keys, f.Key)
+							}
+							assert.Equal(t, tc.expectedKeys, keys, "flag order should be sorted")
+						}
+
+						// Check segments
+						if len(doc.Segments) > 0 {
+							keys := []string{}
+							for _, s := range doc.Segments {
+								keys = append(keys, s.Key)
+							}
+							assert.Equal(t, tc.expectedKeys, keys, "segment order should be sorted")
+						}
+
+						// Check variants
+						if len(doc.Flags) > 0 && len(doc.Flags[0].Variants) > 0 {
+							keys := []string{}
+							for _, v := range doc.Flags[0].Variants {
+								keys = append(keys, v.Key)
+							}
+							assert.Equal(t, tc.expectedKeys, keys, "variant order should be sorted")
+						}
+					}
+				}
+			})
+		}
+	}
+}
