+// TestExportSortByKeyCaseSensitive tests that sorting is case-sensitive
+func TestExportSortByKeyCaseSensitive(t *testing.T) {
+	lister := mockLister{
+		namespaces: map[string]*flipt.Namespace{
+			"0_default": {
+				Key:         "default",
+				Name:        "default",
+				Description: "default namespace",
+			},
+		},
+		nsToFlags: map[string][]*flipt.Flag{
+			"default": {
+				{
+					Key:         "Flag1",
+					Name:        "Flag1",
+					Type:        flipt.FlagType_VARIANT_FLAG_TYPE,
+					Description: "Flag1",
+					Enabled:     true,
+					Variants:    []*flipt.Variant{{Id: "1", Key: "A"}},
+				},
+				{
+					Key:         "flag1",
+					Name:        "flag1",
+					Type:        flipt.FlagType_VARIANT_FLAG_TYPE,
+					Description: "flag1",
+					Enabled:     true,
+					Variants:    []*flipt.Variant{{Id: "2", Key: "B"}},
+				},
+			},
+		},
+		nsToSegments: map[string][]*flipt.Segment{
+			"default": {},
+		},
+		nsToRules:    map[string][]*flipt.Rule{},
+		nsToRollouts: map[string][]*flipt.Rollout{},
+	}
+
+	exporter := NewExporter(lister, "default", false, true)
+	b := new(bytes.Buffer)
+
+	err := exporter.Export(context.Background(), EncodingYML, b)
+	require.NoError(t, err)
+
+	decoder := EncodingYML.NewDecoder(b)
+	var doc Document
+	err = decoder.Decode(&doc)
+	require.NoError(t, err)
+
+	// In case-sensitive sorting, uppercase letters come before lowercase
+	// So "Flag1" < "flag1" (F < f in ASCII)
+	assert.Len(t, doc.Flags, 2)
+	assert.Equal(t, "Flag1", doc.Flags[0].Key)
+	assert.Equal(t, "flag1", doc.Flags[1].Key)
+}
