+					Variants:    []*flipt.Variant{{Id: "2", Key: "a"}},
+				},
+			},
+		},
+		nsToSegments: map[string][]*flipt.Segment{
+			"default": {},
+		},
+		nsToRules:    map[string][]*flipt.Rule{},
+		nsToRollouts: map[string][]*flipt.Rollout{},
+	}
+
+	// Without sortByKey, order should be preserved as-is
+	exporter := NewExporter(lister, "default", false, false)
+	b := new(bytes.Buffer)
+
+	err := exporter.Export(context.Background(), EncodingYML, b)
+	require.NoError(t, err)
+
+	decoder := EncodingYML.NewDecoder(b)
+	var doc Document
+	err = decoder.Decode(&doc)
+	require.NoError(t, err)
+
+	// Order should be zebra first, then apple (as provided)
+	assert.Len(t, doc.Flags, 2)
+	assert.Equal(t, "zebra", doc.Flags[0].Key)
+	assert.Equal(t, "apple", doc.Flags[1].Key)
+}

