--- a/internal/server/auth/middleware.go
+++ b/internal/server/auth/middleware.go
@@ -107,9 +107,19 @@ func UnaryInterceptor(logger *zap.Logger, authenticator Authenticator, o ...cont

 		auth, err := authenticator.GetAuthenticationByClientToken(ctx, clientToken)
 		if err != nil {
+			// Check if the error is due to context cancellation or deadline exceeded
+			// If so, propagate the correct gRPC code instead of converting to Unauthenticated
+			if st, ok := status.FromError(err); ok {
+				switch st.Code() {
+				case codes.Canceled, codes.DeadlineExceeded:
+					return ctx, err
+				}
+			}
+
 			logger.Error("unauthenticated",
 				zap.String("reason", "error retrieving authentication for client token"),
 				zap.Error(err))
+
 			return ctx, errUnauthenticated
 		}

