+// FormatWithRange returns the formatted CVSS score with the severity-derived range.
+// If there's no numeric score, returns just the severity with range.
+func (c Cvss) FormatWithRange() string {
+	if c.Score == 0 || c.Vector == "" {
+		rangeStr := c.SeverityToCvssScoreRange()
+		return fmt.Sprintf("%s (%s)", c.Severity, rangeStr)
+	}
+	switch c.Type {
+	case CVSS2:
+		return fmt.Sprintf("%3.1f/%s %s", c.Score, c.Vector, c.Severity)
+	case CVSS3:
+		return fmt.Sprintf("%3.1f/%s %s", c.Score, c.Vector, c.Severity)
+	}
+	return ""
+}
+
+
+// SeverityToCvssScoreRange returns a CVSS score range string mapped from the Severity attribute
+// of the Cvss struct, enabling consistent representation of severity levels as CVSS score ranges.
+// This is used when a CVE has a severity label but no numeric CVSS score.
+func (c Cvss) SeverityToCvssScoreRange() string {
+	switch strings.ToUpper(c.Severity) {
+	case "CRITICAL":
+		return "9.0-10.0"
+	case "IMPORTANT", "HIGH":
+		return "7.0-8.9"
+	case "MODERATE", "MEDIUM":
+		return "4.0-6.9"
+	case "LOW":
+		return "0.1-3.9"
+	}
+	return "N/A"
+}
