+func TestParseInstalledPackagesLineWithModularityLabel(t *testing.T) {
+	r := newRHEL(config.ServerInfo{})
+
+	var packagetests = []struct {
+		in   string
+		pack models.Package
+		err  bool
+	}{
+		{
+			// 6-field format with modularity label
+			"nginx 0 1.16.1 1.module+el8.3.0+8844+e5e7039f.1 x86_64 nginx:1.16",
+			models.Package{
+				Name:            "nginx",
+				Version:         "1.16.1",
+				Release:         "1.module+el8.3.0+8844+e5e7039f.1",
+				Arch:            "x86_64",
+				ModularityLabel: "nginx:1.16",
+			},
+			false,
+		},
+		{
+			// 6-field format with (none) modularity label
+			"openssl 0 1.0.1e 30.el6.11 x86_64 (none)",
+			models.Package{
+				Name:            "openssl",
+				Version:         "1.0.1e",
+				Release:         "30.el6.11",
+				Arch:            "x86_64",
+				ModularityLabel: "",
+			},
+			false,
+		},
+		{
+			// 5-field format (no modularity label)
+			"openssl 0 1.0.1e 30.el6.11 x86_64",
