+// parseLsOfListen parses lsof output to map pid -> []ListenPort
+func (l *base) parseLsOfListen(stdout string) map[string][]models.ListenPort {
+	result := map[string][]models.ListenPort{}
+	scanner := bufio.NewScanner(strings.NewReader(stdout))
+	for scanner.Scan() {
+		line := scanner.Text()
+		ss := strings.Fields(line)
+		if len(ss) < 10 {
+			continue
+		}
+		pid, ipPort := ss[1], ss[8]
+		
+		// Parse the ip:port into structured format
+		lp := l.parseListenPorts(ipPort)
+		
+		result[pid] = append(result[pid], lp)
+	}
+	return result
+}
+
+// scanListenPorts scans the listening ports and updates PortScanSuccessOn.
+// It attempts TCP connections to all detected endpoints and records which ones are reachable.
+func (l *base) scanListenPorts() error {
+	// Detect scan destinations from affected processes
+	dests := l.detectScanDest()
+	
+	if len(dests) == 0 {
+		return nil
+	}
+	
+	// Try to connect to each destination with a short timeout
+	successful := []string{}
+	timeout := 1 * time.Second
+	
+	for _, dest := range dests {
+		// Parse ip:port
+		addrPort := dest
+		conn, err := net.DialTimeout("tcp", addrPort, timeout)
+		if err == nil {
+			successful = append(successful, addrPort)
+			conn.Close()
+		}
+		// Connection failed or timeout - port not reachable
+	}
+	
+	// Update PortScanSuccessOn for all packages
+	l.updatePortStatus(successful)
+	
+	return nil
+}
+
+func (l *base) detectScanDest() []string {
+	dests := map[string]struct{}{}
+	
+	// Get host IPv4 addresses
+	hostIPv4Addrs := l.ServerInfo.IPv4Addrs
+	
+	for _, pkg := range l.Packages {
+		for _, proc := range pkg.AffectedProcs {
+			for _, listenPort := range proc.ListenPorts {
+				addr := listenPort.Address
+				port := listenPort.Port
+				
+				if addr == "*" {
+					// Expand wildcard to all host IPv4 addresses
+					for _, ip := range hostIPv4Addrs {
+						dests[fmt.Sprintf("%s:%s", ip, port)] = struct{}{}
+					}
+				} else {
+					// Exact address match (including IPv6 with brackets)
+					dests[fmt.Sprintf("%s:%s", addr, port)] = struct{}{}
+				}
+			}
+		}
+	}
+	
+	// Convert to slice and sort for deterministic ordering
+	result := make([]string, 0, len(dests))
+	for dest := range dests {
+		result = append(result, dest)
+	}
+	
+	// Sort to ensure deterministic order
+	sort.Strings(result)
+	
+	return result
+}
+
+// updatePortStatus updates PortScanSuccessOn in place for packages based on scan results.
+// listenIPPorts is a slice of "ip:port" strings that were successfully scanned.
+func (l *base) updatePortStatus(listenIPPorts []string) {
+	// Create a map for quick lookup of successful ports
+	successMap := make(map[string]bool)
+	for _, lip := range listenIPPorts {
+		successMap[lip] = true
+	}
+	
+	// Update each package's affected processes
+	for pkgName, pkg := range l.Packages {
+		for i := range pkg.AffectedProcs {
+			proc := &pkg.AffectedProcs[i]
+			for j := range proc.ListenPorts {
+				lp := &proc.ListenPorts[j]
+				lp.PortScanSuccessOn = l.findPortScanSuccessOn(listenIPPorts, *lp)
+			}
+		}
+		l.Packages[pkgName] = pkg
+	}
+}
+
+// findPortScanSuccessOn finds the IPv4 addresses where the listen port was confirmed reachable.
+// It always returns a non-nil slice (empty slice when no matches).
+func (l *base) findPortScanSuccessOn(listenIPPorts []string, searchListenPort models.ListenPort) []string {
+	successOn := []string{}
+	
+	// Get host IPv4 addresses for wildcard expansion
+	hostIPv4Addrs := l.ServerInfo.IPv4Addrs
+	seen := make(map[string]bool)
+	
+	for _, ipPort := range listenIPPorts {
+		// Parse ip:port
+		addr := searchListenPort.Address
+		port := searchListenPort.Port
+		
+		if addr == "*" {
+			// For wildcard, check if the port matches any host IPv4 address
+			for _, hostIP := range hostIPv4Addrs {
+				if strings.HasSuffix(ipPort, fmt.Sprintf(":%s", port)) {
+					if !seen[hostIP] {
+						successOn = append(successOn, hostIP)
+						seen[hostIP] = true
+					}
+				}
+			}
+		} else {
+			// For exact address, check for exact match (including IPv6 with brackets)
+			expected := fmt.Sprintf("%s:%s", addr, port)
+			if ipPort == expected {
+				// Extract the IP part from the successful scan result
+				if parts := strings.Split(ipPort, ":"); len(parts) >= 2 {
+					ip := strings.Join(parts[:len(parts)-1], ":")
+					if !seen[ip] {
+						successOn = append(successOn, ip)
+						seen[ip] = true
+					}
+				}
+			}
+		}
+	}
+	
+	// Deduplicate and return non-nil slice
+	if successOn == nil {
+		successOn = []string{}
+	}
+	
+	return successOn
+}
+
+// parseListenPorts parses a listen port string into a ListenPort struct.
+// It supports formats like "127.0.0.1:22", "*:80", and "[::1]:443" (IPv6 with brackets).
+func (l *base) parseListenPorts(s string) models.ListenPort {
+	result := models.ListenPort{
+		Address:         "",
+		Port:            "",
+		PortScanSuccessOn: []string{},
+	}
+	
+	// Handle empty string
+	if s == "" {
+		return result
+	}
+	
+	// For IPv6 with brackets, find the last colon after the closing bracket
+	if strings.Contains(s, "]") {
+		// Find the last colon
+		lastColonIdx := strings.LastIndex(s, ":")
+		if lastColonIdx > 0 {
+			result.Address = s[:lastColonIdx]
+			result.Port = s[lastColonIdx+1:]
+		} else {
+			// Fallback: treat whole string as address
+			result.Address = s
+			result.Port = ""
+		}
+	} else {
+		// For IPv4 or hostname, split on the last colon
+		lastColonIdx := strings.LastIndex(s, ":")
+		if lastColonIdx > 0 {
+			result.Address = s[:lastColonIdx]
+			result.Port = s[lastColonIdx+1:]
+		} else {
+			// No colon found or just a port number
+			result.Address = s
+			result.Port = ""
+		}
+	}
+	
+	return result
+}
