+++ b/scanner/scanner_test_windows.go
@@ -0,0 +1,86 @@
+package scanner
+
+import (
+	"os"
+	"runtime"
+	"testing"
+)
+
+func TestNormalizeHomeDirPathForWindows(t *testing.T) {
+	// Save original USERPROFILE
+	origUserProfile := os.Getenv("USERPROFILE")
+	defer os.Setenv("USERPROFILE", origUserProfile)
+
+	// Set test USERPROFILE
+	os.Setenv("USERPROFILE", "C:\\Users\\TestUser")
+
+	tests := []struct {
+		name     string
+		input    string
+		expected string
+	}{
+		{
+			name:     "tilde with forward slash",
+			input:    "~/.ssh/known_hosts",
+			expected: "C:\\Users\\TestUser\\.ssh\\known_hosts",
+		},
+		{
+			name:     "tilde with backslash",
+			input:    "~\\ssh\\known_hosts",
+			expected: "C:\\Users\\TestUser\\ssh\\known_hosts",
+		},
+		{
+			name:     "just tilde",
+			input:    "~",
+			expected: "C:\\Users\\TestUser",
+		},
+		{
+			name:     "tilde with trailing slash",
+			input:    "~/",
+			expected: "C:\\Users\\TestUser",
+		},
+		{
+			name:     "non-tilde path",
+			input:    "/etc/ssh/known_hosts",
+			expected: "/etc/ssh/known_hosts",
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			result := normalizeHomeDirPathForWindows(tt.input)
+			if result != tt.expected {
+				t.Errorf("normalizeHomeDirPathForWindows(%q) = %q, want %q", tt.input, result, tt.expected)
+			}
+		})
+	}
+}
+
+func TestParseSSHConfiguration_WindowsPathExpansion(t *testing.T) {
+	// Test that on Windows, ~ paths are expanded
+	if runtime.GOOS != "windows" {
+		t.Skip("Skipping Windows-specific test on non-Windows OS")
+	}
+
+	// Set test USERPROFILE
+	os.Setenv("USERPROFILE", "C:\\Users\\TestUser")
+
+	sshConfigOutput := "user root\nhostname 127.0.0.1\nuserknownhostsfile ~/.ssh/known_hosts ~/.ssh/known_hosts2\n"
+
+	sshConfig := parseSSHConfiguration(sshConfigOutput)
+
+	expectedKnownHosts := []string{"C:\\Users\\TestUser\\.ssh\\known_hosts", "C:\\Users\\TestUser\\.ssh\\known_hosts2"}
+	if len(sshConfig.userKnownHosts) != len(expectedKnownHosts) {
+		t.Errorf("Expected %d known hosts, got %d", len(expectedKnownHosts), len(sshConfig.userKnownHosts))
+	}
+
+	for i, expected := range expectedKnownHosts {
+		if i >= len(sshConfig.userKnownHosts) {
+			t.Errorf("Missing expected known host at index %d: %q", i, expected)
+			continue
+		}
+		if sshConfig.userKnownHosts[i] != expected {
+			t.Errorf("Expected known host %d to be %q, got %q", i, expected, sshConfig.userKnownHosts[i])
+		}
+	}
+}

