+// Ref: https://github.com/openai/openai-cookbook/blob/594fc6c952425810e9ea5bd1a275c8ca5f32e8f9/examples/How_to_count_tokens_with_tiktoken.ipynb
+const (
+	// perMessage is the token "overhead" for each message
+	perMessage = 3
+
+	// perRequest is the number of tokens used up for each completion request
+	perRequest = 3
+
+	// perRole is the number of tokens used to encode a message's role
+	perRole = 1
+)
+
+// TokenCounters is a slice of TokenCounter.
+type TokenCounters []TokenCounter
+
+// TokenCounter defines a contract for token counters.
+// The TokenCount() method returns the counter's value.
+type TokenCounter interface {
+	TokenCount() int
+}
+
+// TokenCount aggregates prompt and completion token counters for a single agent invocation.
+type TokenCount struct {
+	promptCounters     []TokenCounter
+	completionCounters []TokenCounter
+}
+
+// AddPromptCounter appends a prompt-side counter; nil inputs are ignored.
+func (tc *TokenCount) AddPromptCounter(prompt TokenCounter) {
+	if prompt != nil {
+		tc.promptCounters = append(tc.promptCounters, prompt)
+	}
+}
+
+// AddCompletionCounter appends a completion-side counter; nil inputs are ignored.
+func (tc *TokenCount) AddCompletionCounter(completion TokenCounter) {
+	if completion != nil {
+		tc.completionCounters = append(tc.completionCounters, completion)
+	}
+}
+
+// CountAll returns (promptTotal, completionTotal) by summing all counters.
+func (tc *TokenCount) CountAll() (int, int) {
+	promptTotal := tc.promptCounters.CountAll()
+	completionTotal := tc.completionCounters.CountAll()
+	return promptTotal, completionTotal
+}
+
+// CountAll sums the totals of all contained counters.
+func (tc TokenCounters) CountAll() int {
+	total := 0
+	for _, counter := range tc {
+		if counter != nil {
+			total += counter.TokenCount()
+		}
+	}
+	return total
+}
+
+// StaticTokenCounter is a fixed-value token counter.
+type StaticTokenCounter struct {
+	count int
+}
+
+// TokenCount returns the stored integer value of the static counter.
+func (s *StaticTokenCounter) TokenCount() int {
+	return s.count
+}
+
+// NewTokenCount creates and returns an empty TokenCount.
+func NewTokenCount() *TokenCount {
+	return &TokenCount{
+		promptCounters:     make([]TokenCounter, 0),
+		completionCounters: make([]TokenCounter, 0),
+	}
+}
+
+// NewPromptTokenCounter computes prompt token usage for a list of messages
+// using the cl100k_base tokenizer and returns a static counter.
+func NewPromptTokenCounter(messages []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
+	enc := codec.NewCl100kBase()
+	total := 0
+
+	for _, message := range messages {
+		tokens, _, err := enc.Encode(message.Content)
+		if err != nil {
+			return nil, trace.Wrap(err, "failed to encode message content")
+		}
+		total += perMessage + perRole + len(tokens)
+	}
+
+	return &StaticTokenCounter{count: total}, nil
+}
+
+// NewSynchronousTokenCounter computes completion token usage for a full,
+// non-streamed response using the cl100k_base tokenizer.
+func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
+	enc := codec.NewCl100kBase()
+	tokens, _, err := enc.Encode(completion)
+	if err != nil {
+		return nil, trace.Wrap(err, "failed to encode completion")
+	}
+
+	return &StaticTokenCounter{count: perRequest + len(tokens)}, nil
+}
+
+// AsynchronousTokenCounter is a streaming-aware counter for completion tokens.
+type AsynchronousTokenCounter struct {
+	count      int
+	finished   bool
+	startCount int
+}
+
+// Add increments the streamed token count by one. Returns an error if the
+// counter has already been finalized by a call to TokenCount().
+func (a *AsynchronousTokenCounter) Add() error {
+	if a.finished {
+		return errors.New("asynchronous token counter has already been finalized")
+	}
+	a.count++
+	return nil
+}
+
+// TokenCount finalizes the counter and returns the total token count including perRequest.
+// Marks the counter as finished; subsequent calls to Add() must return an error.
+func (a *AsynchronousTokenCounter) TokenCount() int {
+	if !a.finished {
+		a.finished = true
+		return perRequest + a.startCount + a.count
+	}
+	return perRequest + a.startCount + a.count
+}
+
+// NewAsynchronousTokenCounter initializes an AsynchronousTokenCounter with the
+// tokenized starting fragment of a streamed completion.
+func NewAsynchronousTokenCounter(start string) (*AsynchronousTokenCounter, error) {
+	enc := codec.NewCl100kBase()
+	tokens, _, err := enc.Encode(start)
+	if err != nil {
+		return nil, trace.Wrap(err, "failed to encode start")
+	}
+
+	return &AsynchronousTokenCounter{
+		count:      0,
+		finished:   false,
+		startCount: len(tokens),
+	}, nil
+}

