+// buildKubeConfigUpdate builds a kubeconfig.Values struct for updating
+// kubeconfig based on the CLI configuration and client state.
+//
+// This function returns a Values struct without modifying the current context.
+// The caller is responsible for updating the current context if needed.
+func buildKubeConfigUpdate(cf *CLIConf, tc *client.TeleportClient, kubeClusters []string) (kubeconfig.Values, error) {
+	var v kubeconfig.Values
+
+	v.ClusterAddr = tc.KubeClusterAddr()
+	v.TeleportClusterName = tc.KubeProxyHostPort()
+	if tc.SiteName != "" {
+		v.TeleportClusterName = tc.SiteName
+	}
+
+	// Get the credentials from the local agent.
+	creds, err := tc.LocalAgent().GetCoreKey()
+	if err != nil {
+		return v, trace.Wrap(err)
+	}
+	v.Credentials = creds
+
+	// Check if the proxy supports Kubernetes. If not, skip kubeconfig updates.
+	if tc.KubeProxyAddr == "" {
+		// Proxy doesn't support Kubernetes, skip kubeconfig updates.
+		return v, nil
+	}
+
+	// Determine the SelectCluster value based on --kube-cluster flag.
+	// This is set only when the user explicitly specifies --kube-cluster.
+	selectCluster := cf.KubernetesCluster
+
+	// Validate the requested kubernetes cluster if specified.
+	if selectCluster != "" {
+		if !utils.SliceContainsStr(kubeClusters, selectCluster) {
+			return v, trace.BadParameter("kubernetes cluster %q is not registered in this teleport cluster; you can list registered kubernetes clusters using 'tsh kube ls'", selectCluster)
+		}
+	}
+
+	// If we have tsh binary path and clusters available, configure exec plugin.
+	if cf.executablePath != "" && len(kubeClusters) > 0 {
+		v.Exec = &kubeconfig.ExecValues{
+			TshBinaryPath:     cf.executablePath,
+			TshBinaryInsecure: tc.InsecureSkipVerify,
+			KubeClusters:      kubeClusters,
+			// Only set SelectCluster if --kube-cluster was specified
+			SelectCluster:     selectCluster,
+		}
+	} else {
+		// No tsh binary path or clusters available, use static credentials.
+		v.Exec = nil
+	}
+
+	return v, nil
+}
+
+// updateKubeConfig updates the kubeconfig with the given values.
+// This function skips updates if the proxy lacks Kubernetes support.
+func updateKubeConfig(ctx context.Context, path string, v kubeconfig.Values) error {
+	// Skip kubeconfig updates if proxy lacks Kubernetes support or no exec configuration.
+	if v.Exec == nil || len(v.Exec.KubeClusters) == 0 {
+		return nil
+	}
+	return kubeconfig.Update(path, v)
+}
