+// MakeTableWithTruncatedColumn creates a table that adapts to terminal size
+// and truncates the specified column to keep readability. The truncatedColumn
+// parameter specifies which column should expand to fill remaining space and
+// be truncated if its content exceeds the available width.
+// If the terminal size cannot be determined, a default width of 80 characters is used.
+// If the truncatedColumn name does not match any column header, the table is still
+// rendered correctly with all columns preserved.
+func MakeTableWithTruncatedColumn(columnOrder []string, rows [][]string, truncatedColumn string) Table {
+	width, _, err := term.GetSize(int(os.Stdin.Fd()))
+	if err != nil {
+		width = 80
+	}
+	truncatedColMinSize := 16
+	maxColWidth := (width - truncatedColMinSize) / (len(columnOrder) - 1)
+	t := MakeTable([]string{})
+	totalLen := 0
+	columns := []Column{}
+
+	for colIndex, colName := range columnOrder {
+		column := Column{
+			Title:         colName,
+			MaxCellLength: len(colName),
+		}
+		if colName == truncatedColumn {
+			columns = append(columns, column)
+			continue
+		}
+		for _, row := range rows {
+			if colIndex < len(row) {
+				cellLen := row[colIndex]
+				if len(cellLen) > column.MaxCellLength {
+					column.MaxCellLength = len(cellLen)
+				}
+			}
+		}
+		if column.MaxCellLength > maxColWidth {
+			column.MaxCellLength = maxColWidth
+			totalLen += column.MaxCellLength + 4 // "...<space>"
+		} else {
+			totalLen += column.MaxCellLength + 1 // +1 for column separator
+		}
+		columns = append(columns, column)
+	}
+
+	for i, column := range columns {
+		if column.Title == truncatedColumn {
+			columns[i].MaxCellLength = width - totalLen - len("... ")
+			if columns[i].MaxCellLength < truncatedColMinSize {
+				columns[i].MaxCellLength = truncatedColMinSize
+			}
+		}
+		t.AddColumn(columns[i])
+	}
+
+	for _, row := range rows {
+		t.AddRow(row)
+	}
+	return t
+}
+
