+	}
+
+	err := e.cfg.Inner.EmitAuditEvent(ctx, we.event)
+
+	if err == nil {
+		// Success - if we were in backoff, reset it
+		if e.inBackoff.Swap(false) {
+			log.WithFields(log.Fields{
+				trace.Component: e.cfg.Component,
+			}).Info("Async emitter exited backoff mode")
+		}
+		return
+	}
+
+	// Check if the error indicates we should enter backoff
+	if e.isBackoffError(err) {
+		e.handleBackoff(err, we)
+		return
+	}
+
+	// Slow write (timeout, etc.)
+	if err == context.DeadlineExceeded || trace.IsTimeout(err) {
+		e.slowWrites.Inc()
+		e.handleSlowWrite(ctx, we)
+		return
+	}
+
+	// Other errors - log and continue
+	log.WithFields(log.Fields{
+		trace.Component: e.cfg.Component,
+		"error":         err,
+	}).Debug("Async emitter event processing error")
+}
+
+// isBackoffError checks if the error indicates a connection/write failure that should trigger backoff
+func (e *AsyncEmitter) isBackoffError(err error) bool {
+	// Connection problems, timeouts, and other recoverable errors trigger backoff
+	if trace.IsConnectionProblem(err) || trace.IsTimeout(err) || trace.IsNotFound(err) {
+		return true
+	}
+	// Check for common teleport error types
+	if _, ok := err.(interface{ Temporary() bool }); ok {
+		return true
+	}
+	return false
+}
+
+// handleBackoff enters backoff mode for BackoffDuration
+func (e *AsyncEmitter) handleBackoff(err error, we wrappedEvent) {
+	e.inBackoff.Store(true)
+	now := e.cfg.Clock.Now()
+	e.backoffUntil.Store(now.Add(e.cfg.BackoffDuration).UnixNano())
+
+	log.WithFields(log.Fields{
+		trace.Component: e.cfg.Component,
+		"error":         err,
+		"duration":      e.cfg.BackoffDuration,
+	}).Warning("Async emitter entered backoff mode")
+
+	// Drop the current event
+	e.lostEvents.Inc()
+	e.recordLostReason("backoff_error")
+}
+
+// handleSlowWrite handles a slow write by retrying with bounded timeout
+func (e *AsyncEmitter) handleSlowWrite(ctx context.Context, we wrappedEvent) {
+	// Record this as a slow write
+	e.slowWrites.Inc()
+
+	// Try to send again with the remaining timeout
+	remaining := e.cfg.BackoffTimeout - (e.cfg.BackoffTimeout / 2)
+	if remaining <= 0 {
+		remaining = time.Second
+	}
+
+	retryCtx, cancel := context.WithTimeout(we.ctx, remaining)
+	defer cancel()
+
+	// Retry once with remaining time
+	err := e.cfg.Inner.EmitAuditEvent(retryCtx, we.event)
+	if err != nil {
+		e.lostEvents.Inc()
+		e.recordLostReason("slow_write_timeout")
+
+		// Enter backoff if this was a persistent failure
+		if e.isBackoffError(err) {
+			e.handleBackoff(err, we)
+		}
+		return
+	}
+
+	// Success after slow write - reset backoff if needed
+	if e.inBackoff.Swap(false) {
+		log.WithFields(log.Fields{
+			trace.Component: e.cfg.Component,
+		}).Info("Async emitter exited backoff mode after retry")
+	}
+}
+
+// checkBackoffTimeout checks if backoff period has expired and resets if so
+func (e *AsyncEmitter) checkBackoffTimeout() {
+	if !e.inBackoff.Load() {
+		return
+	}
+
+	now := e.cfg.Clock.Now()
+	backoffEnd := time.Unix(0, e.backoffUntil.Load())
+
+	if now.After(backoffEnd) {
+		if e.inBackoff.Swap(false) {
+			log.WithFields(log.Fields{
+				trace.Component: e.cfg.Component,
+			}).Info("Async emitter backoff period expired, resuming operations")
+		}
+	}
+}
+
+// recordLostReason records why an event was lost for debugging
+func (e *AsyncEmitter) recordLostReason(reason string) {
+	e.statsMtx.Lock()
+	defer e.statsMtx.Unlock()
+	e.lostReasons[reason]++
+}
+
+// Stats returns a snapshot of the audit writer counters
+func (e *AsyncEmitter) Stats() AuditWriterStats {
+	return AuditWriterStats{
+		AcceptedEvents: e.acceptedEvents.Load(),
+		LostEvents:     e.lostEvents.Load(),
+		SlowWrites:     e.slowWrites.Load(),
+	}
+}
+
+// Close cancels the background processing and prevents further submissions
+func (e *AsyncEmitter) Close() error {
+	e.cancel()
+	return nil
+}
+
+// CreateAuditStream implements Streamer interface
+func (e *AsyncEmitter) CreateAuditStream(ctx context.Context, sid session.ID) (Stream, error) {
+	return e.cfg.Inner.CreateAuditStream(ctx, sid)
+}
+
+// ResumeAuditStream implements Streamer interface
+func (e *AsyncEmitter) ResumeAuditStream(ctx context.Context, sid session.ID, uploadID string) (Stream, error) {
+	return e.cfg.Inner.ResumeAuditStream(ctx, sid, uploadID)
+}
+
+// LoggingAsyncEmitter wraps AsyncEmitter with additional logging
+type LoggingAsyncEmitter struct {
+	*AsyncEmitter
+}
+
+// NewLoggingAsyncEmitter creates an async emitter with logging for losses
+func NewLoggingAsyncEmitter(cfg AsyncEmitterConfig) (*LoggingAsyncEmitter, error) {
+	ae, err := NewAsyncEmitter(cfg)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return &LoggingAsyncEmitter{AsyncEmitter: ae}, nil
+}
+
+// EmitAuditEvent logs lost events at debug level
+func (l *LoggingAsyncEmitter) EmitAuditEvent(ctx context.Context, event AuditEvent) error {
+	err := l.AsyncEmitter.EmitAuditEvent(ctx, event)
+	if err != nil {
+		log.WithFields(log.Fields{
+			trace.Component: l.cfg.Component,
+			"error":         err,
+			"type":          event.GetType(),
+		}).Debug("Async emitter dropped event")
+	}
+	return err
+}
+
+// StreamWithBackoff wraps a Stream with backoff handling for slow writes
+type StreamWithBackoff struct {
+	Stream
+	emitter *AsyncEmitter
+}
+
+// EmitAuditEvent wraps stream emit with backoff handling
+func (s *StreamWithBackoff) EmitAuditEvent(ctx context.Context, event AuditEvent) error {
+	return s.emitter.EmitAuditEvent(ctx, event)
+}
