+
+func TestCriteriaToSql(t *testing.T) {
+	// Test empty criteria
+	c := &Criteria{}
+	sql, _, err := c.ToSql()
+	assert.NoError(t, err)
+	assert.Equal(t, "1=1", sql)
+
+	// Test with expression
+	c = &Criteria{
+		Expression: Eq{"id": 1},
+	}
+	sql, _, err = c.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "id")
+}
+
+func TestFieldMap(t *testing.T) {
+	// Test field mapping
+	assert.Equal(t, "media_file.title", MapField("title"))
+	assert.Equal(t, "media_file.artist", MapField("artist"))
+	assert.Equal(t, "media_file.album", MapField("album"))
+	assert.Equal(t, "annotation.starred", MapField("loved"))
+	assert.Equal(t, "media_file.year", MapField("year"))
+	assert.Equal(t, "media_file.comment", MapField("comment"))
+	
+	// Test unmapped field
+	assert.Equal(t, "custom", MapField("custom"))
+}
+
+func TestContainsOperator(t *testing.T) {
+	op := Contains{Field: "title", Value: "hello"}
+	sql, args, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "ILIKE")
+	assert.Contains(t, sql, "media_file.title")
+	assert.Equal(t, "%hello%", args[0])
+}
+
+func TestNotContainsOperator(t *testing.T) {
+	op := NotContains{Field: "artist", Value: "test"}
+	sql, args, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "NOT ILIKE")
+	assert.Contains(t, sql, "media_file.artist")
+	assert.Equal(t, "%test%", args[0])
+}
+
+func TestStartsWithOperator(t *testing.T) {
+	op := StartsWith{Field: "album", Value: "best"}
+	sql, args, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "ILIKE")
+	assert.Contains(t, sql, "media_file.album")
+	assert.Equal(t, "best%", args[0])
+}
+
+func TestEndsWithOperator(t *testing.T) {
+	op := EndsWith{Field: "artist", Value: "end"}
+	sql, args, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "ILIKE")
+	assert.Contains(t, sql, "media_file.artist")
+	assert.Equal(t, "%end", args[0])
+}
+
+func TestInTheRangeOperator(t *testing.T) {
+	minTime := Time(time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC))
+	maxTime := Time(time.Date(2020, 12, 31, 23, 59, 59, 0, time.UTC))
+	op := InTheRange{Field: "year", Min: minTime, Max: maxTime}
+	sql, args, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, ">=")
+	assert.Contains(t, sql, "<=")
+	assert.Equal(t, 2, len(args))
+}
+
+func TestInTheLastOperator(t *testing.T) {
+	op := InTheLast{Field: "play_date", Days: 7}
+	sql, _, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, ">")
+	assert.Contains(t, sql, "play_date")
+}
+
+func TestNotInTheLastOperator(t *testing.T) {
+	op := NotInTheLast{Field: "play_date", Days: 7}
+	sql, _, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "<")
+	assert.Contains(t, sql, "IS NULL")
+}
+
+func TestAllOperator(t *testing.T) {
+	// Use squirrel's And type
+	all := And{Eq{"a": 1}, Eq{"b": 2}}
+	sql, _, err := all.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "AND")
+}
+
+func TestAnyOperator(t *testing.T) {
+	// Use squirrel's Or type
+	any := Or{Eq{"a": 1}, Eq{"b": 2}}
+	sql, _, err := any.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "OR")
+}
+
+func TestTimeMarshalJSON(t *testing.T) {
+	tm := Time(time.Date(2020, 5, 15, 0, 0, 0, 0, time.UTC))
+	data, err := json.Marshal(tm)
+	assert.NoError(t, err)
+	assert.Equal(t, `"2020-05-15"`, string(data))
+}
+
+func TestTimeUnmarshalJSON(t *testing.T) {
+	var tm Time
+	err := json.Unmarshal([]byte(`"2020-05-15"`), &tm)
+	assert.NoError(t, err)
+	assert.Equal(t, "2020-05-15", tm.Time().Format("2006-01-02"))
+}
+
+func TestIsOperator(t *testing.T) {
+	op := Eq{"title": "hello"}
+	sql, _, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "=")
+}
+
+func TestIsNotOperator(t *testing.T) {
+	op := NotEq{"artist": "test"}
+	sql, _, err := op.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "<>") // squirrel uses <> for not equal
+}
+
+func TestCriteriaMarshalJSON(t *testing.T) {
+	// Use squirrel's And type directly
+	c := &Criteria{
+		Expression: And{
+			Eq{"title": "hello"},
+			Eq{"artist": "world"},
+		},
+		Sort:   "title",
+		Order:  "ASC",
+		Max:    10,
+		Offset: 0,
+	}
+	
+	data, err := json.Marshal(c)
+	assert.NoError(t, err)
+	
+	var result map[string]interface{}
+	err = json.Unmarshal(data, &result)
+	assert.NoError(t, err)
+	
+	// Check that 'all' key exists
+	assert.Contains(t, result, "all", "Expected 'all' key for nested And expression")
+}
+
+func TestCriteriaUnmarshalJSON(t *testing.T) {
+	jsonStr := `{
+		"all": [
+			{"is": "hello"},
+			{"contains": "world"}
+		],
+		"sort": "title",
+		"order": "ASC",
+		"max": 10,
+		"offset": 0
+	}`
+	
+	c := &Criteria{}
+	err := json.Unmarshal([]byte(jsonStr), c)
+	assert.NoError(t, err)
+	assert.NotNil(t, c.Expression)
+	assert.Equal(t, "title", c.Sort)
+	assert.Equal(t, "ASC", c.Order)
+	assert.Equal(t, 10, c.Max)
+	assert.Equal(t, 0, c.Offset)
+}
+
+func TestNestedLogicalOperators(t *testing.T) {
+	c := &Criteria{
+		Expression: And{
+			Or{
+				Eq{"title": "hello"},
+				Eq{"title": "world"},
+			},
+			Eq{"artist": "test"},
+		},
+	}
+	
+	sql, _, err := c.ToSql()
+	assert.NoError(t, err)
+	// Should have both AND and OR
+	assert.Contains(t, sql, "AND")
+	assert.Contains(t, sql, "OR")
+}
+
+func TestBuildSQL(t *testing.T) {
+	c := &Criteria{
+		Expression: Eq{"title": "test"},
+		Sort:       "artist",
+		Order:      "DESC",
+		Max:        20,
+		Offset:     10,
+	}
+	
+	sql, _, err := c.BuildSQL("media_file")
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "WHERE")
+	assert.Contains(t, sql, "ORDER BY media_file.artist DESC")
+	assert.Contains(t, sql, "LIMIT 20")
+	assert.Contains(t, sql, "OFFSET 10")
+}
+
+func TestBuildCountSQL(t *testing.T) {
+	c := &Criteria{
+		Expression: Eq{"title": "test"},
+	}
+	
+	sql, _, err := c.BuildCountSQL("media_file")
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "SELECT COUNT(*)")
+	assert.Contains(t, sql, "WHERE")
+}
+
+func TestAddCondition(t *testing.T) {
+	c := &Criteria{}
+	c = c.AddCondition(Eq{"title": "hello"})
+	c = c.AddCondition(Eq{"artist": "world"})
+	
+	sql, _, err := c.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "AND")
+}
+
+func TestAddAnyCondition(t *testing.T) {
+	c := &Criteria{}
+	c = c.AddAnyCondition(Eq{"title": "hello"})
+	c = c.AddAnyCondition(Eq{"title": "world"})
+	
+	sql, _, err := c.ToSql()
+	assert.NoError(t, err)
+	assert.Contains(t, sql, "OR")
+}
+
+func TestPaginate(t *testing.T) {
+	c := &Criteria{}
+	c = c.Paginate(50, 100)
+	
+	assert.Equal(t, 50, c.Max)
+	assert.Equal(t, 100, c.Offset)
+}
+
+func TestSortBy(t *testing.T) {
+	c := &Criteria{}
+	c = c.SortBy("title", "desc")
+	
+	assert.Equal(t, "title", c.Sort)
+	assert.Equal(t, "desc", c.Order)
+}
