@@ -0,0 +1,65 @@
+package criteria
+
+import (
+	"encoding/json"
+	"time"
+)
+
+// fieldMap maps interface field names to fully qualified SQL columns
+var fieldMap = map[string]string{
+	"title":   "media_file.title",
+	"artist":  "media_file.artist",
+	"album":   "media_file.album",
+	"loved":   "annotation.starred",
+	"year":    "media_file.year",
+	"comment": "media_file.comment",
+}
+
+// Time is a date type that serializes to JSON as string in ISO 8601 format
+type Time time.Time
+
+// NewTime creates a Time from a time.Time
+func NewTime(t time.Time) Time {
+	return Time(t)
+}
+
+// Time returns the time.Time value
+func (t Time) Time() time.Time {
+	return time.Time(t)
+}
+
+// MarshalJSON serializes Time to JSON as string in ISO 8601 2006-01-02 format
+func (t Time) MarshalJSON() ([]byte, error) {
+	tm := time.Time(t)
+	formatted := tm.Format("2006-01-02")
+	return json.Marshal(formatted)
+}
+
+// UnmarshalJSON deserializes Time from JSON
+func (t *Time) UnmarshalJSON(data []byte) error {
+	var s string
+	if err := json.Unmarshal(data, &s); err != nil {
+		return err
+	}
+	
+	tm, err := time.Parse("2006-01-02", s)
+	if err != nil {
+		return err
+	}
+	
+	*t = Time(tm)
+	return nil
+}
+
+// GetFieldMap returns the field mapping
+func GetFieldMap() map[string]string {
+	return fieldMap
+}
+
+// MapField maps a field name to its SQL column equivalent
+func MapField(fieldName string) string {
+	if mapped, ok := fieldMap[fieldName]; ok {
+		return mapped
+	}
+	return fieldName
+}
diff --git a/model/criteria/json.go b/model/criteria/json.go
new file mode 100644
index 00000000..e96fcc9e
--- /dev/null
+++ b/model/criteria/json.go
@@ -0,0 +1,402 @@
+package criteria
+
+import (
+	"encoding/json"
+	"fmt"
+	"time"
+
+	. "github.com/Masterminds/squirrel"
+)
+
+// JSONCriteria represents the JSON structure for Criteria
+type JSONCriteria struct {
+	All        []interface{} `json:"all,omitempty"`
+	Any        []interface{} `json:"any,omitempty"`
+	Contains   string        `json:"contains,omitempty"`
+	NotContains string       `json:"notContains,omitempty"`
+	Is         string        `json:"is,omitempty"`
+	IsNot      string        `json:"isNot,omitempty"`
+	Gt         string        `json:"gt,omitempty"`
+	Lt         string        `json:"lt,omitempty"`
+	Before     string        `json:"before,omitempty"`
+	After      string        `json:"after,omitempty"`
+	StartsWith string        `json:"startsWith,omitempty"`
+	EndsWith   string        `json:"endsWith,omitempty"`
+	InTheRange map[string]interface{} `json:"inTheRange,omitempty"`
+	InTheLast  map[string]interface{} `json:"inTheLast,omitempty"`
+	NotInTheLast map[string]interface{} `json:"notInTheLast,omitempty"`
+	Sort       string        `json:"sort,omitempty"`
+	Order      string        `json:"order,omitempty"`
+	Max        int           `json:"max,omitempty"`
+	Offset     int           `json:"offset,omitempty"`
+}
+
+// MarshalJSON serializes criteria to JSON format
+func (c *Criteria) MarshalJSON() ([]byte, error) {
+	if c.Expression == nil {
+		// No expression, just return pagination info
+		jsonCrit := JSONCriteria{
+			Sort:   c.Sort,
+			Order:  c.Order,
+			Max:    c.Max,
+			Offset: c.Offset,
+		}
+		return json.Marshal(jsonCrit)
+	}
+	
+	// Serialize the expression
+	jsonExpr, err := serializeExpression(c.Expression)
+	if err != nil {
+		return nil, err
+	}
+	
+	// Create the JSON structure
+	result := make(map[string]interface{})
+	
+	// Add the expression type (all or any)
+	for k, v := range jsonExpr {
+		result[k] = v
+	}
+	
+	// Add pagination fields
+	if c.Sort != "" {
+		result["sort"] = c.Sort
+	}
+	if c.Order != "" {
+		result["order"] = c.Order
+	}
+	if c.Max > 0 {
+		result["max"] = c.Max
+	}
+	if c.Offset > 0 {
+		result["offset"] = c.Offset
+	}
+	
+	return json.Marshal(result)
+}
+
+// UnmarshalJSON deserializes criteria from JSON
+func (c *Criteria) UnmarshalJSON(data []byte) error {
+	var raw map[string]interface{}
+	if err := json.Unmarshal(data, &raw); err != nil {
+		return err
+	}
+	
+	var expr Sqlizer = nil
+	
+	// Process each field
+	for key, value := range raw {
+		switch key {
+		case "all":
+			if arr, ok := value.([]interface{}); ok {
+				operands, err := deserializeOperands(arr)
+				if err != nil {
+					return err
+				}
+				expr = All(operands)
+			}
+		case "any":
+			if arr, ok := value.([]interface{}); ok {
+				operands, err := deserializeOperands(arr)
+				if err != nil {
+					return err
+				}
+				expr = Any(operands)
+			}
+		case "contains":
+			if s, ok := value.(string); ok {
+				expr = Contains{Field: "", Value: s}
+			}
+		case "notContains":
+			if s, ok := value.(string); ok {
+				expr = NotContains{Field: "", Value: s}
+			}
+		case "is":
+			if s, ok := value.(string); ok {
+				expr = Is{"": s}
+			}
+		case "isNot":
+			if s, ok := value.(string); ok {
+				expr = IsNot{"": s}
+			}
+		case "gt":
+			// Skip, handled via field
+		case "lt":
+			// Skip, handled via field
+		case "before":
+			// Skip, handled via field
+		case "after":
+			// Skip, handled via field
+		case "startsWith":
+			if s, ok := value.(string); ok {
+				expr = StartsWith{Field: "", Value: s}
+			}
+		case "endsWith":
+			if s, ok := value.(string); ok {
+				expr = EndsWith{Field: "", Value: s}
+			}
+		case "inTheRange":
+			if m, ok := value.(map[string]interface{}); ok {
+				minStr := m["min"].(string)
+				maxStr := m["max"].(string)
+				min, _ := time.Parse("2006-01-02", minStr)
+				max, _ := time.Parse("2006-01-02", maxStr)
+				expr = InTheRange{Field: "", Min: Time(min), Max: Time(max)}
+			}
+		case "inTheLast":
+			if m, ok := value.(map[string]interface{}); ok {
+				days := int(m["days"].(float64))
+				expr = InTheLast{Field: "", Days: days}
+			}
+		case "notInTheLast":
+			if m, ok := value.(map[string]interface{}); ok {
+				days := int(m["days"].(float64))
+				expr = NotInTheLast{Field: "", Days: days}
+			}
+		case "sort":
+			c.Sort = value.(string)
+		case "order":
+			c.Order = value.(string)
+		case "max":
+			c.Max = int(value.(float64))
+		case "offset":
+			c.Offset = int(value.(float64))
+		}
+	}
+	
+	c.Expression = expr
+	return nil
+}
+
+// serializeExpression converts a Sqlizer to JSON representation
+func serializeExpression(expr Sqlizer) (map[string]interface{}, error) {
+	result := make(map[string]interface{})
+	
+	switch e := expr.(type) {
+	case And:
+		operands := make([]interface{}, 0)
+		for _, op := range e {
+			serialized, err := serializeExpression(op)
+			if err != nil {
+				return nil, err
+			}
+			operands = append(operands, serialized)
+		}
+		result["all"] = operands
+	case Or:
+		operands := make([]interface{}, 0)
+		for _, op := range e {
+			serialized, err := serializeExpression(op)
+			if err != nil {
+				return nil, err
+			}
+			operands = append(operands, serialized)
+		}
+		result["any"] = operands
+	case All:
+		// Handle All type alias
+		operands := make([]interface{}, 0)
+		for _, op := range e {
+			serialized, err := serializeExpression(op)
+			if err != nil {
+				return nil, err
+			}
+			operands = append(operands, serialized)
+		}
+		result["all"] = operands
+	case Any:
+		// Handle Any type alias
+		operands := make([]interface{}, 0)
+		for _, op := range e {
+			serialized, err := serializeExpression(op)
+			if err != nil {
+				return nil, err
+			}
+			operands = append(operands, serialized)
+		}
+		result["any"] = operands
+	case Is:
+		for _, v := range e {
+			result["is"] = fmt.Sprintf("%v", v)
+		}
+	case IsNot:
+		for _, v := range e {
+			result["isNot"] = fmt.Sprintf("%v", v)
+		}
+	case Eq:
+		// For Eq, we need to extract the field and value
+		for field, val := range e {
+			result["is"] = fmt.Sprintf("%v", val)
+			result["_field"] = field
+		}
+	case NotEq:
+		for field, val := range e {
+			result["isNot"] = fmt.Sprintf("%v", val)
+			result["_field"] = field
+		}
+	case Contains:
+		result["contains"] = e.Value
+		result["_field"] = e.Field
+	case NotContains:
+		result["notContains"] = e.Value
+		result["_field"] = e.Field
+	case StartsWith:
+		result["startsWith"] = e.Value
+		result["_field"] = e.Field
+	case EndsWith:
+		result["endsWith"] = e.Value
+		result["_field"] = e.Field
+	case InTheRange:
+		result["inTheRange"] = map[string]interface{}{
+			"min": e.Min.Time().Format("2006-01-02"),
+			"max": e.Max.Time().Format("2006-01-02"),
+		}
+		result["_field"] = e.Field
+	case InTheLast:
+		result["inTheLast"] = map[string]interface{}{
+			"days": e.Days,
+		}
+		result["_field"] = e.Field
+	case NotInTheLast:
+		result["notInTheLast"] = map[string]interface{}{
+			"days": e.Days,
+		}
+		result["_field"] = e.Field
+	default:
+		// For unknown types, serialize to raw SQL
+		sql, args, err := expr.ToSql()
+		if err == nil {
+			result["raw"] = fmt.Sprintf("%s %v", sql, args)
+		}
+	}
+	
+	return result, nil
+}
+
+// deserializeOperands converts JSON array to Sqlizer slice
+func deserializeOperands(arr []interface{}) ([]Sqlizer, error) {
+	operands := make([]Sqlizer, 0)
+	for _, item := range arr {
+		if nested, ok := item.(map[string]interface{}); ok {
+			op, err := deserializeExpression(nested)
+			if err != nil {
+				return nil, err
+			}
+			operands = append(operands, op)
+		}
+	}
+	return operands, nil
+}
+
+// deserializeExpression converts JSON object to Sqlizer
+func deserializeExpression(obj map[string]interface{}) (Sqlizer, error) {
+	for key, value := range obj {
+		switch key {
+		case "all":
+			if arr, ok := value.([]interface{}); ok {
+				operands, err := deserializeOperands(arr)
+				if err != nil {
+					return nil, err
+				}
+				return All(operands), nil
+			}
+		case "any":
+			if arr, ok := value.([]interface{}); ok {
+				operands, err := deserializeOperands(arr)
+				if err != nil {
+					return nil, err
+				}
+				return Any(operands), nil
+			}
+		case "is":
+			if s, ok := value.(string); ok {
+				// Find the field name from the obj
+				for k, _ := range obj {
+					if k != "is" && k != "_field" {
+						return Is{k: s}, nil
+					}
+				}
+				return Is{"": s}, nil
+			}
+		case "isNot":
+			if s, ok := value.(string); ok {
+				for k, _ := range obj {
+					if k != "isNot" && k != "_field" {
+						return IsNot{k: s}, nil
+					}
+				}
+				return IsNot{"": s}, nil
+			}
+		case "contains":
+			if s, ok := value.(string); ok {
+				for k, _ := range obj {
+					if k != "contains" && k != "_field" {
+						return Contains{Field: k, Value: s}, nil
+					}
+				}
+				return Contains{Field: "", Value: s}, nil
+			}
+		case "notContains":
+			if s, ok := value.(string); ok {
+				for k, _ := range obj {
+					if k != "notContains" && k != "_field" {
+						return NotContains{Field: k, Value: s}, nil
+					}
+				}
+				return NotContains{Field: "", Value: s}, nil
+			}
+		case "startsWith":
+			if s, ok := value.(string); ok {
+				for k, _ := range obj {
+					if k != "startsWith" && k != "_field" {
+						return StartsWith{Field: k, Value: s}, nil
+					}
+				}
+				return StartsWith{Field: "", Value: s}, nil
+			}
+		case "endsWith":
+			if s, ok := value.(string); ok {
+				for k, _ := range obj {
+					if k != "endsWith" && k != "_field" {
+						return EndsWith{Field: k, Value: s}, nil
+					}
+				}
+				return EndsWith{Field: "", Value: s}, nil
+			}
+		case "inTheRange":
+			if m, ok := value.(map[string]interface{}); ok {
+				minStr := m["min"].(string)
+				maxStr := m["max"].(string)
+				min, _ := time.Parse("2006-01-02", minStr)
+				max, _ := time.Parse("2006-01-02", maxStr)
+				for k, _ := range obj {
+					if k != "inTheRange" && k != "_field" {
+						return InTheRange{Field: k, Min: Time(min), Max: Time(max)}, nil
+					}
+				}
+				return InTheRange{Field: "", Min: Time(min), Max: Time(max)}, nil
+			}
+		case "inTheLast":
+			if m, ok := value.(map[string]interface{}); ok {
+				days := int(m["days"].(float64))
+				for k, _ := range obj {
+					if k != "inTheLast" && k != "_field" {
+						return InTheLast{Field: k, Days: days}, nil
+					}
+				}
+				return InTheLast{Field: "", Days: days}, nil
+			}
+		case "notInTheLast":
+			if m, ok := value.(map[string]interface{}); ok {
+				days := int(m["days"].(float64))
+				for k, _ := range obj {
+					if k != "notInTheLast" && k != "_field" {
+						return NotInTheLast{Field: k, Days: days}, nil
+					}
+				}
+				return NotInTheLast{Field: "", Days: days}, nil
+			}
+		}
+	}
+	return nil, nil
+}
diff --git a/model/criteria/operators.go b/model/criteria/operators.go
new file mode 100644
index 00000000..8e50c69a
--- /dev/null
+++ b/model/criteria/operators.go
@@ -0,0 +1,239 @@
+package criteria
+
+import (
+	"encoding/json"
+	"fmt"
+	"time"
+
+	. "github.com/Masterminds/squirrel"
+)
+
+// All is a type alias of squirrel.And for logical conjunctions
+type All And
+
+// Any is a type alias of squirrel.Or for logical disjunctions
+type Any Or
+
+// Is is an exact equality operator based on squirrel.Eq
+type Is Eq
+
+// IsNot is an inequality operator based on squirrel.NotEq
+type IsNot NotEq
+
+// Contains is a text search operator with %value% pattern
+type Contains struct {
+	Field string
+	Value string
+}
+
+// NotContains is a text exclusion operator with %value% pattern
+type NotContains struct {
+	Field string
+	Value string
+}
+
+// StartsWith is a prefix search operator with value% pattern
+type StartsWith struct {
+	Field string
+	Value string
+}
+
+// EndsWith is a suffix search operator with %value pattern
+type EndsWith struct {
+	Field string
+	Value string
+}
+
+// InTheRange is a numeric or date range operator
+type InTheRange struct {
+	Field string
+	Min   Time
+	Max   Time
+}
+
+// InTheLast is an operator for dates within the last N days
+type InTheLast struct {
+	Field string
+	Days  int
+}
+
+// NotInTheLast is an operator for dates NOT within the last N days
+type NotInTheLast struct {
+	Field string
+	Days  int
+}
+
+// ToSql generates SQL with AND between conditions for All
+func (a All) ToSql() (string, []interface{}, error) {
+	return And(a).ToSql()
+}
+
+// ToSql generates SQL with OR between conditions for Any
+func (a Any) ToSql() (string, []interface{}, error) {
+	return Or(a).ToSql()
+}
+
+// ToSql generates equality SQL for Is
+func (i Is) ToSql() (string, []interface{}, error) {
+	return Eq(i).ToSql()
+}
+
+// ToSql generates inequality SQL for IsNot
+func (n IsNot) ToSql() (string, []interface{}, error) {
+	return NotEq(n).ToSql()
+}
+
+// ToSql generates ILIKE SQL with %value% pattern for Contains
+func (c Contains) ToSql() (string, []interface{}, error) {
+	field := MapField(c.Field)
+	pattern := "%" + c.Value + "%"
+	return fmt.Sprintf("%s ILIKE ?", field), []interface{}{pattern}, nil
+}
+
+// ToSql generates NOT ILIKE SQL with %value% pattern for NotContains
+func (n NotContains) ToSql() (string, []interface{}, error) {
+	field := MapField(n.Field)
+	pattern := "%" + n.Value + "%"
+	return fmt.Sprintf("%s NOT ILIKE ?", field), []interface{}{pattern}, nil
+}
+
+// ToSql generates ILIKE SQL with value% pattern for StartsWith
+func (s StartsWith) ToSql() (string, []interface{}, error) {
+	field := MapField(s.Field)
+	pattern := s.Value + "%"
+	return fmt.Sprintf("%s ILIKE ?", field), []interface{}{pattern}, nil
+}
+
+// ToSql generates ILIKE SQL with %value pattern for EndsWith
+func (e EndsWith) ToSql() (string, []interface{}, error) {
+	field := MapField(e.Field)
+	pattern := "%" + e.Value
+	return fmt.Sprintf("%s ILIKE ?", field), []interface{}{pattern}, nil
+}
+
+// ToSql generates SQL with >= and <= conditions for InTheRange
+func (r InTheRange) ToSql() (string, []interface{}, error) {
+	field := MapField(r.Field)
+	sql := fmt.Sprintf("%s >= ? AND %s <= ?", field, field)
+	args := []interface{}{r.Min.Time(), r.Max.Time()}
+	return sql, args, nil
+}
+
+// ToSql generates greater than calculated date SQL for InTheLast
+func (l InTheLast) ToSql() (string, []interface{}, error) {
+	field := MapField(l.Field)
+	date := time.Now().AddDate(0, 0, -l.Days)
+	return fmt.Sprintf("%s > ?", field), []interface{}{date}, nil
+}
+
+// ToSql generates SQL with OR of less than calculated date or IS NULL for NotInTheLast
+func (n NotInTheLast) ToSql() (string, []interface{}, error) {
+	field := MapField(n.Field)
+	date := time.Now().AddDate(0, 0, -n.Days)
+	sql := fmt.Sprintf("%s < ? OR %s IS NULL", field, field)
+	args := []interface{}{date}
+	return sql, args, nil
+}
+
+// MarshalJSON serializes All to JSON with key "all"
+func (a All) MarshalJSON() ([]byte, error) {
+	result := make(map[string]interface{})
+	operands := make([]interface{}, 0)
+	for _, op := range a {
+		serialized, err := serializeExpression(op)
+		if err != nil {
+			return nil, err
+		}
+		operands = append(operands, serialized)
+	}
+	result["all"] = operands
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes Any to JSON with key "any"
+func (a Any) MarshalJSON() ([]byte, error) {
+	result := make(map[string]interface{})
+	operands := make([]interface{}, 0)
+	for _, op := range a {
+		serialized, err := serializeExpression(op)
+		if err != nil {
+			return nil, err
+		}
+		operands = append(operands, serialized)
+	}
+	result["any"] = operands
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes Is to JSON with key "is"
+func (i Is) MarshalJSON() ([]byte, error) {
+	result := make(map[string]interface{})
+	for _, v := range i {
+		result["is"] = fmt.Sprintf("%v", v)
+	}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes IsNot to JSON with key "isNot"
+func (n IsNot) MarshalJSON() ([]byte, error) {
+	result := make(map[string]interface{})
+	for _, v := range n {
+		result["isNot"] = fmt.Sprintf("%v", v)
+	}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes Contains to JSON with key "contains"
+func (c Contains) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{"contains": c.Value}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes NotContains to JSON with key "notContains"
+func (n NotContains) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{"notContains": n.Value}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes StartsWith to JSON with key "startsWith"
+func (s StartsWith) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{"startsWith": s.Value}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes EndsWith to JSON with key "endsWith"
+func (e EndsWith) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{"endsWith": e.Value}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes InTheRange to JSON with key "inTheRange"
+func (r InTheRange) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{
+		"inTheRange": map[string]interface{}{
+			"min": r.Min.Time().Format("2006-01-02"),
+			"max": r.Max.Time().Format("2006-01-02"),
+		},
+	}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes InTheLast to JSON with key "inTheLast"
+func (l InTheLast) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{
+		"inTheLast": map[string]interface{}{
+			"days": l.Days,
+		},
+	}
+	return json.Marshal(result)
+}
+
+// MarshalJSON serializes NotInTheLast to JSON with key "notInTheLast"
+func (n NotInTheLast) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{
+		"notInTheLast": map[string]interface{}{
+			"days": n.Days,
+		},
+	}
+	return json.Marshal(result)
+}

