+package cmd
+
+import (
+	"context"
+	"fmt"
+	"os"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/db"
+	"github.com/navidrome/navidrome/log"
+	"github.com/spf13/cobra"
+)
+
+var backupCmd *cobra.Command
+var backupCreateCmd *cobra.Command
+var backupPruneCmd *cobra.Command
+var backupRestoreCmd *cobra.Command
+
+func init() {
+	backupCmd = &cobra.Command{
+		Use:   "backup",
+		Short: "Manage database backups",
+		Long:  `Manage database backups: create, restore, and prune backups.`,
+	}
+
+	backupCreateCmd = &cobra.Command{
+		Use:   "create",
+		Short: "Create a manual database backup",
+		Long:  `Create a manual database backup. This command ignores the configured backup.count.`,
+		RunE:  runBackupCreate,
+	}
+
+	backupPruneCmd = &cobra.Command{
+		Use:   "prune",
+		Short: "Remove old database backups",
+		Long: `Remove old database backups, keeping only the latest configured number.
+If backup.count is 0, requires --force flag unless confirmed interactively.`,
+		RunE: runBackupPrune,
+	}
+
+	backupRestoreCmd = &cobra.Command{
+		Use:   "restore",
+		Short: "Restore database from a backup file",
+		Long:  `Restore the database from a specified backup file. Requires confirmation unless --force is provided.`,
+		RunE:  runBackupRestore,
+	}
+
+	backupPruneCmd.Flags().Bool("force", false, "Force operation without confirmation")
+	backupRestoreCmd.Flags().String("backup-file", "", "Path to the backup file to restore")
+	backupRestoreCmd.Flags().Bool("force", false, "Force operation without confirmation")
+
+	backupCmd.AddCommand(backupCreateCmd)
+	backupCmd.AddCommand(backupPruneCmd)
+	backupCmd.AddCommand(backupRestoreCmd)
+	rootCmd.AddCommand(backupCmd)
+}
+
+func runBackupCreate(cmd *cobra.Command, args []string) error {
+	ctx := cmd.Context()
+	log.Info("Creating database backup...")
+	dbInstance := db.Db()
+	backupPath, err := dbInstance.Backup(ctx)
+	if err != nil {
+		return fmt.Errorf("failed to create backup: %w", err)
+	}
+	log.Info("Backup created successfully", "path", backupPath)
+	return nil
+}
+
+func runBackupPrune(cmd *cobra.Command, args []string) error {
+	count := conf.Server.Backup.Count
+
+	// Check if count is 0 and force flag is not set
+	force := backupPruneCmd.Flag("force").Value.String() == "true"
+	if count == 0 && !force {
+		if !confirm("backup.count is set to 0. This will delete all backups. Are you sure?") {
+			log.Info("Backup pruning cancelled")
+			return nil
+		}
+	}
+
+	log.Info("Pruning old database backups...", "keep", count)
+	dbInstance := db.Db()
+	removed, err := dbInstance.Prune(cmd.Context())
+	if err != nil {
+		return fmt.Errorf("failed to prune backups: %w", err)
+	}
+	log.Info("Backup pruning completed", "removed", removed)
+	return nil
+}
+
+func runBackupRestore(cmd *cobra.Command, args []string) error {
+	backupFile := backupRestoreCmd.Flag("backup-file").Value.String()
+	if backupFile == "" {
+		log.Fatal("Backup file path is required. Use --backup-file flag.")
+	}
+
+	// Check if force flag is not set
+	force := backupRestoreCmd.Flag("force").Value.String() == "true"
+	if !force {
+		if !confirm(fmt.Sprintf("Restore database from %s? This will overwrite the current database.", backupFile)) {
+			log.Info("Backup restore cancelled")
+			return nil
+		}
+	}
+
+	log.Info("Restoring database from backup...", "path", backupFile)
+	dbInstance := db.Db()
+	if err := dbInstance.Restore(cmd.Context(), backupFile); err != nil {
+		return fmt.Errorf("failed to restore backup: %w", err)
+	}
+	log.Info("Database restored successfully")
+	return nil
+}
+
+func confirm(message string) bool {
+	fmt.Printf("%s [y/N] ", message)
+	var response string
+	_, err := fmt.Scanln(&response)
+	if err != nil {
+		return false
+	}
+	if len(response) == 0 {
+		return false
+	}
+	firstChar := response[0]
+	return firstChar == 'y' || firstChar == 'Y'
+}
+
+// ScheduleBackup starts the automatic backup scheduler
+func ScheduleBackup(ctx context.Context) {
+	if !db.ShouldScheduleBackup() {
+		log.Info("Automatic backups are DISABLED")
+		return
+	}
+
+	schedule := db.GetBackupSchedule()
+	count := db.GetBackupCount()
+
+	log.Info("Scheduling periodic backups", "schedule", schedule, "keep", count)
+
+	schedulerInstance := GetScheduler()
+	err := schedulerInstance.Add(schedule, func() {
+		// Create backup
+		dbInstance := db.Db()
+		backupPath, err := dbInstance.Backup(ctx)
+		if err != nil {
+			log.Error("Failed to create backup", "error", err)
+			return
+		}
+		log.Info("Backup created", "path", backupPath)
+
+		// Prune old backups
+		removed, err := dbInstance.Prune(ctx)
+		if err != nil {
+			log.Error("Failed to prune backups", "error", err)
+			return
+		}
+		if removed > 0 {
+			log.Info("Old backups pruned", "removed", removed)
+		}
+	})
+
+	if err != nil {
+		log.Error("Error scheduling periodic backups", "error", err)
+		return
+	}
+
+	log.Debug("Backup scheduler started")
+}
+
+// EnsureBackupPath ensures the backup directory exists on startup
+func EnsureBackupPath() error {
+	backupPath := getBackupPath()
+	if err := os.MkdirAll(backupPath, os.ModePerm); err != nil {
+		return fmt.Errorf("failed to create backup directory: %w", err)
+	}
+	return nil
+}
+
+func getBackupPath() string {
+	if conf.Server.Backup.Path != "" {
+		return conf.Server.Backup.Path
+	}
+	return conf.Server.DataFolder + "/backups"
+}
