diff --git a/db/backup.go b/db/backup.go
new file mode 100644
index 00000000..09b7ea0b
--- /dev/null
+++ b/db/backup.go
@@ -0,0 +1,237 @@
+package db
+
+import (
+	"context"
+	"database/sql"
+	"fmt"
+	"os"
+	"path/filepath"
+	"regexp"
+	"sort"
+	"strings"
+	"time"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/log"
+)
+
+const backupFilenamePrefix = "navidrome_backup_"
+const backupFilenameSuffix = ".db"
+
+var backupFilenameRegex = regexp.MustCompile(`^navidrome_backup_(\d{4}-\d{2}-\d{2}_\d{6})\.db$`)
+
+// Backup creates an online SQLite backup of the current database.
+// It returns the destination backup file path as string alongside an error.
+func (d *db) Backup(ctx context.Context) (string, error) {
+	backupPath := getBackupPath()
+	if err := os.MkdirAll(backupPath, os.ModePerm); err != nil {
+		return "", fmt.Errorf("failed to create backup directory: %w", err)
+	}
+
+	timestamp := time.Now().Format("2006-01-02_150405")
+	backupFile := filepath.Join(backupPath, fmt.Sprintf("%s%s%s", backupFilenamePrefix, timestamp, backupFilenameSuffix))
+
+	// Get the source database path from the current config
+	// We use conf.Server.DbPath which may contain SQLite URL parameters
+	srcPath := conf.Server.DbPath
+
+	// For :memory: databases, we can't back up using file copy
+	if srcPath == ":memory:" || strings.Contains(srcPath, "file::memory:") {
+		return "", fmt.Errorf("backup of in-memory database is not supported. Use a file-based database")
+	}
+
+	// Strip SQLite URL parameters to get the actual file path
+	srcPath = extractSQLiteFilePath(srcPath)
+
+	// Ensure the source database exists and is accessible
+	srcDB, err := sql.Open("sqlite3", srcPath)
+	if err != nil {
+		return "", fmt.Errorf("failed to open source database: %w", err)
+	}
+	defer srcDB.Close()
+
+	if err := srcDB.PingContext(ctx); err != nil {
+		return "", fmt.Errorf("failed to ping source database: %w", err)
+	}
+
+	// For WAL mode databases, we need to ensure all changes are checkpointed
+	// Execute a checkpoint to ensure the main database file is up to date
+	_, _ = srcDB.Exec("PRAGMA wal_checkpoint(PASSIVE)")
+
+	// Create the backup database
+	dst, err := sql.Open("sqlite3", backupFile)
+	if err != nil {
+		return "", fmt.Errorf("failed to open backup file: %w", err)
+	}
+	defer dst.Close()
+
+	// Try VACUUM INTO first (SQLite 3.27.0+)
+	if _, err := dst.ExecContext(ctx, "VACUUM FROM "+srcPath); err != nil {
+		// Fallback to direct file copy
+		if err := copyFile(srcPath, backupFile); err != nil {
+			return "", fmt.Errorf("failed to copy database: %w", err)
+		}
+	}
+
+	return backupFile, nil
+}
+
+// Restore restores the database from the provided backup file located at path.
+// It returns an error indicating success or failure.
+func (d *db) Restore(ctx context.Context, path string) error {
+	// Verify the backup file exists
+	if _, err := os.Stat(path); os.IsNotExist(err) {
+		return fmt.Errorf("backup file does not exist: %s", path)
+	}
+
+	// Verify it's a valid backup file (has correct naming pattern)
+	filename := filepath.Base(path)
+	if !backupFilenameRegex.MatchString(filename) {
+		return fmt.Errorf("invalid backup file name: %s", filename)
+	}
+
+	// Close current database connections
+	d.Close()
+
+	// Copy the backup file to the current database location
+	if err := copyFile(path, conf.Server.DbPath); err != nil {
+		// Try to reopen the original database
+		_ = Db()
+		return fmt.Errorf("failed to restore backup: %w", err)
+	}
+
+	// Reopen the database
+	_ = Db()
+
+	return nil
+}
+
+// Prune removes old backup files according to the configured retention policy.
+// It returns the number of files pruned as int alongside an error.
+func (d *db) Prune(ctx context.Context) (int, error) {
+	backupPath := getBackupPath()
+
+	// Get all backup files
+	files, err := os.ReadDir(backupPath)
+	if err != nil {
+		return 0, fmt.Errorf("failed to read backup directory: %w", err)
+	}
+
+	var backupFiles []string
+	for _, file := range files {
+		if !file.IsDir() && backupFilenameRegex.MatchString(file.Name()) {
+			backupFiles = append(backupFiles, filepath.Join(backupPath, file.Name()))
+		}
+	}
+
+	if len(backupFiles) <= conf.Server.Backup.Count {
+		log.Debug("No backups to prune", "count", len(backupFiles), "keep", conf.Server.Backup.Count)
+		return 0, nil
+	}
+
+	// Sort files by name (which includes timestamp) in descending order
+	sort.Slice(backupFiles, func(i, j int) bool {
+		return backupFiles[i] > backupFiles[j]
+	})
+
+	// Remove old backups, keeping only conf.Server.Backup.Count
+	removed := 0
+	for i := conf.Server.Backup.Count; i < len(backupFiles); i++ {
+		if err := os.Remove(backupFiles[i]); err != nil {
+			log.Error("Failed to remove old backup", "file", backupFiles[i], "error", err)
+			continue
+		}
+		removed++
+		log.Info("Removed old backup", "file", filepath.Base(backupFiles[i]))
+	}
+
+	return removed, nil
+}
+
+// getBackupPath returns the directory where backups should be stored
+func getBackupPath() string {
+	if conf.Server.Backup.Path != "" {
+		return conf.Server.Backup.Path
+	}
+	// Default to data folder
+	return filepath.Join(conf.Server.DataFolder, "backups")
+}
+
+// copyFile copies a file from src to dst
+func copyFile(src, dst string) error {
+	sourceFile, err := os.Open(src)
+	if err != nil {
+		return err
+	}
+	defer sourceFile.Close()
+
+	// Create the destination directory if it doesn't exist
+	dstDir := filepath.Dir(dst)
+	if err := os.MkdirAll(dstDir, os.ModePerm); err != nil {
+		return err
+	}
+
+	destFile, err := os.Create(dst)
+	if err != nil {
+		return err
+	}
+	defer destFile.Close()
+
+	_, err = destFile.ReadFrom(sourceFile)
+	return err
+}
+
+// extractSQLiteFilePath extracts the actual file path from a SQLite URL
+// e.g., "navidrome.db?cache=shared&_cache_size=1000000000" -> "navidrome.db"
+// or "file:/path/to/db.db?..." -> "/path/to/db.db"
+func extractSQLiteFilePath(url string) string {
+	// If it starts with "file:", extract the path after "file:"
+	if strings.HasPrefix(url, "file:") {
+		url = strings.TrimPrefix(url, "file:")
+		// Remove leading slash that might be part of the scheme separator
+		url = strings.TrimPrefix(url, "/")
+	}
+
+	// Remove query parameters (everything after ?)
+	if idx := strings.Index(url, "?"); idx != -1 {
+		url = url[:idx]
+	}
+
+	return url
+}
+
+// normalizeSchedule converts a duration string to a cron expression
+func normalizeSchedule(schedule string) string {
+	if schedule == "" {
+		return ""
+	}
+
+	// Check if it's a valid duration
+	if _, err := time.ParseDuration(schedule); err == nil {
+		return "@every " + schedule
+	}
+
+	// Already a cron expression, return as is
+	return schedule
+}
+
+// ShouldScheduleBackup returns true if automatic backups should be scheduled
+func ShouldScheduleBackup() bool {
+	// Disable scheduling if path is empty, schedule is empty, or count is 0
+	return conf.Server.Backup.Path != "" &&
+		conf.Server.Backup.Schedule != "" &&
+		conf.Server.Backup.Count > 0
+}
+
+// GetBackupSchedule returns the normalized cron schedule for backups
+func GetBackupSchedule() string {
+	if !ShouldScheduleBackup() {
+		return ""
+	}
+	return normalizeSchedule(conf.Server.Backup.Schedule)
+}
+
+// GetBackupCount returns the number of backups to retain
+func GetBackupCount() int {
+	return conf.Server.Backup.Count
+}
