+//
+// The constructor function is called exactly once per type parameter T.
+// Value types and pointer types are treated as distinct types (T and *T are independent).
+//
+// This function is concurrency-safe: multiple goroutines can call GetInstance
+// simultaneously with the same type, and the constructor will run only once.
+func GetInstance[T any](constructor func() T) T {
+	initOnce.Do(func() {
+		atomic.StorePointer(&instances, unsafe.Pointer(&sync.Map{}))
