+
+/**
+ * Returns the next valid expiration time interval for the provided date.
+ * If the date is today, the returned value is a Date object representing
+ * the next available time slot, rounded to the nearest 30-minute step
+ * and guaranteed to be at least 30 minutes later than the current time.
+ * If the date is not today, the function returns undefined so that all
+ * times remain selectable.
+ */
+export const getMinExpirationTime = (date: Date): Date | undefined => {
+    // If date is not today, there is no min time because we want to display all intervals
+    if (!isToday(date)) {
+        return undefined;
+    }
+
+    const now = new Date();
+    
+    // The minimum time we need is strictly later than now AND at least 30 minutes ahead
+    const minRequiredTime = now.getTime() + 30 * 60 * 1000;
+    
+    // Start with a base at the current hour with 0 minutes
+    const nextIntervalDate = new Date(now);
+    nextIntervalDate.setMinutes(0, 0, 0);
+    
+    // Keep adding 30 minutes until we reach a time that meets our requirements
+    while (nextIntervalDate.getTime() < minRequiredTime) {
+        nextIntervalDate.setMinutes(nextIntervalDate.getMinutes() + 30);
+    }
+    
+    return nextIntervalDate;
+};

