+import { pipe } from '@proton/pass/utils/fp/pipe';
+
+export const recoveryItemsIntent = createAction('items::recovery::intent', () =>
+    pipe(
+        withRequest({ status: 'start', id: itemsRecoveryRequest() }),
+        withNotification({
+            type: 'info',
+            text: c('Info').t`Recovering items...`,
