+    'items::recovery::failure',
+    withRequestFailure((error: unknown) =>
+        withNotification({
+            type: 'error',
+            text: c('Error').t`Recovering items failed`,
+            error,
+        })({ payload: {}, error })
+    )
+);
+
+export const recoveryItemsProgress = createAction(
+    'items::recovery::progress',
