@@ -0,0 +1,37 @@
+import { END, eventChannel } from 'redux-saga';
+import noop from '@proton/utils/noop';
+
+import type { ItemRevision } from '@proton/pass/types';
+
+export type BulkRecoveryChannel = {
+    type: 'progress' | 'done' | 'error';
+    progress?: number;
+    data?: ItemRevision;
+    error?: unknown;
+};
+
+export const bulkRecoveryChannel = (items: ItemRevision[]) =>
+    eventChannel<BulkRecoveryChannel>((emitter) => {
+        let completed = 0;
+        const total = items.length;
+        
+        const processNext = async () => {
+            try {
+                for (let i = 0; i < items.length; i++) {
+                    const item = items[i];
+                    completed++;
+                    emitter({ type: 'progress', progress: (completed / total) * 100, data: item });
+                }
+                
+                emitter({ type: 'done' });
+            } catch (error) {
+                emitter({ type: 'error', error });
+            } finally {
+                emitter(END);
+            }
+        };
+        
+        processNext();
+        
+        return noop;
+    });
diff --git a/packages/pass/store/sagas/vaults/recovery-items.saga.ts b/packages/pass/store/sagas/vaults/recovery-items.saga.ts
new file mode 100644
index 0000000000..0de5a16245
--- /dev/null
+++ b/packages/pass/store/sagas/vaults/recovery-items.saga.ts
@@ -0,0 +1,50 @@
+import { put, select, take, takeLeading } from 'redux-saga/effects';
+
+import { recoveryItemsFailure, recoveryItemsIntent, recoveryItemsProgress, recoveryItemsSuccess } from '@proton/pass/store/actions';
+import { type BulkRecoveryChannel, bulkRecoveryChannel } from '@proton/pass/store/sagas/items/item-bulk-recovery.saga';
+import { selectTrashedItems, selectItems } from '@proton/pass/store/selectors';
+import type { RootSagaOptions } from '@proton/pass/store/types';
+import type { BatchItemRevisions, ItemRevision } from '@proton/pass/types';
+
+function* recoveryItemsWorker({ onItemsUpdated }: RootSagaOptions, { meta }: ReturnType<typeof recoveryItemsIntent>) {
+    const requestId = meta.request.id;
+    
+    const trashedItems: ItemRevision[] = yield select(selectTrashedItems);
+    const regularItems: ItemRevision[] = yield select(selectItems);
+    
+    const allItems: ItemRevision[] = [...regularItems, ...trashedItems];
+    
+    const channel = bulkRecoveryChannel(allItems);
+
+    try {
+        while (true) {
+            const action: BulkRecoveryChannel = yield take(channel);
+            onItemsUpdated?.();
+
+            if (action.type === 'progress') {
+                const recoveredItems: ItemRevision[] = action.data ? [action.data] : [];
+                const payload: BatchItemRevisions & { recoveredItems: ItemRevision[] } = {
+                    shareId: action.data?.shareId ?? '',
+                    batch: recoveredItems,
+                    recoveredItems,
+                };
+                const progress = action.progress ?? 0;
+                yield put(recoveryItemsProgress(requestId, progress, payload));
+            }
+            if (action.type === 'done') {
+                yield put(recoveryItemsSuccess(requestId));
+                return;
+            }
+            if (action.type === 'error') {
+                yield put(recoveryItemsFailure(requestId, action.error));
+                return;
+            }
+        }
+    } finally {
+        channel.close();
+    }
+}
+
+export default function* watcher(options: RootSagaOptions) {
+    yield takeLeading(recoveryItemsIntent.match, recoveryItemsWorker, options);
+}
