+import { EVENT_ACTIONS } from '@proton/shared/lib/constants';
+import type { Api } from '@proton/shared/lib/interfaces';
+import type { SavedPaymentMethod } from '@proton/components/payments/core';
+import type { EventItemUpdate } from '@proton/shared/lib/helpers/updateCollection';
+
+/**
+ * Interval between polling attempts in milliseconds.
+ */
+export const interval = 5000;
+
+/**
+ * Maximum number of polling attempts.
+ */
+export const maxPollingSteps = 5;
+
+/**
+ * Options for the pollPaymentMethods function.
+ */
+export interface PollPaymentMethodsOptions {
+    /**
+     * Optional property key to subscribe to (e.g., "PaymentMethod").
+     */
+    propertyKey?: string;
+    /**
+     * Optional action to listen for (e.g., EVENT_ACTIONS.CREATE).
+     */
+    action?: EVENT_ACTIONS;
+}
+
+/**
+ * Result of the polling operation.
+ */
+export interface PollPaymentMethodsResult {
+    /**
+     * The payment method that was added, if detected.
+     */
+    paymentMethod?: SavedPaymentMethod;
+}
+
+/**
+ * Polls for payment method updates after adding a new payment method.
+ * 
+ * This function repeatedly checks for updates because the backend does not
+ * always provide the new method immediately. Events arrive asynchronously.
+ * 
+ * @param api - The API function to call the event endpoint.
+ * @param initialEventID - The initial event ID to begin polling from.
+ * @param options - Optional configuration for property and action filtering.
+ * @returns A promise that resolves when:
+ *          - The expected event is found (if propertyKey and action specified)
+ *          - Maximum polling attempts are reached
+ *          - An error occurs
+ */
+export const pollPaymentMethods = async (
+    api: Api,
+    initialEventID: string,
+    options?: PollPaymentMethodsOptions
+): Promise<PollPaymentMethodsResult> => {
+    const { propertyKey, action } = options || {};
+
+    // Import createEventManager inline to avoid export issues
+    const createEventManager = (api: Api, eventID: string) => {
+        interface EventResponse {
+            EventID: string;
+            More: 0 | 1;
+            [key: string]: any;
+        }
+
+        const listeners: Array<(result: EventResponse) => void> = [];
+        let stateEventID = eventID;
+
+        const subscribe = (listener: (result: EventResponse) => void) => {
+            listeners.push(listener);
+            return () => {
+                const index = listeners.indexOf(listener);
+                if (index !== -1) {
+                    listeners.splice(index, 1);
+                }
+            };
+        };
+
+        const setEventID = (eventID: string) => {
+            stateEventID = eventID;
+        };
+
+        const getEventID = () => {
+            return stateEventID;
+        };
+
+        const call = async () => {
+            const eventID = stateEventID;
+            if (!eventID) {
+                throw new Error('EventID undefined');
+            }
+
+            const result = await api<EventResponse>({
+                url: `core/v5/events/${eventID}`,
+                method: 'get',
+                silence: true,
+            });
+
+            // Notify listeners with the result
+            listeners.forEach((listener) => {
+                try {
+                    listener(result);
+                } catch (e) {
+                    // Ignore listener errors
+                }
+            });
+
+            setEventID(result.EventID);
+        };
+
+        const stop = () => {
+            // No-op for this simple implementation
+        };
+
+        const reset = () => {
+            stateEventID = eventID;
+            listeners.length = 0;
+        };
+
+        return {
+            setEventID,
+            getEventID,
+            start: () => {},
+            stop,
+            call,
+            reset,
+            subscribe,
+        };
+    };
+
+    let eventManager: any | undefined;
+    let unsubscribe: (() => void) | undefined;
+    let currentEventID = initialEventID;
+    let attempts = 0;
+    let foundPaymentMethod: SavedPaymentMethod | undefined;
+
+    try {
+        eventManager = createEventManager(api, currentEventID);
+
+        // If filtering is requested, subscribe to events
+        if (propertyKey && action !== undefined) {
+            unsubscribe = eventManager.subscribe((event: any) => {
+                // Check if this event contains payment method updates
+                const events = event[propertyKey] as EventItemUpdate<SavedPaymentMethod, 'PaymentMethod'>[] | undefined;
+                
+                if (events && Array.isArray(events)) {
+                    for (const eventItem of events) {
+                        // Only check for CREATE or UPDATE actions, as DELETE has no PaymentMethod
+                        if (eventItem.Action === action && eventItem.Action !== EVENT_ACTIONS.DELETE) {
+                            const paymentMethod = (eventItem as any).PaymentMethod as SavedPaymentMethod | undefined;
+                            if (paymentMethod) {
+                                foundPaymentMethod = paymentMethod;
+                                return paymentMethod;
+                            }
+                        }
+                    }
+                }
+                return undefined;
+            });
+        }
+
+        // Start polling with bounded attempts
+        for (attempts = 1; attempts <= maxPollingSteps; attempts++) {
+            try {
+                // Call the event manager to fetch updates
+                await eventManager.call();
+
+                // Get the current event ID after the call
+                const newEventID = eventManager.getEventID();
+                if (newEventID) {
+                    currentEventID = newEventID;
+                }
+
+                // If we found the expected event during subscription, stop early
+                if (foundPaymentMethod) {
+                    break;
+                }
+
+                // Wait for the interval before next poll (except after last attempt)
+                if (attempts < maxPollingSteps) {
+                    await new Promise((resolve) => setTimeout(resolve, interval));
+                }
+            } catch (error) {
+                // Continue polling on error unless it's the last attempt
+                if (attempts < maxPollingSteps) {
+                    await new Promise((resolve) => setTimeout(resolve, interval));
+                    continue;
+                }
+                throw error;
+            }
+        }
+    } finally {
+        // Clean up: stop the event manager and unsubscribe
+        if (eventManager) {
+            eventManager.stop();
+            eventManager.reset();
+        }
+        if (unsubscribe) {
+            unsubscribe();
+        }
+    }
+
+    // Return the results
+    return {
+        paymentMethod: foundPaymentMethod,
+    };
+};
+
+/**
+ * A higher-level polling mechanism that maintains state and provides more control.
+ */
+export interface PaymentMethodPoller {
+    /**
+     * Start polling for payment method updates.
+     */
+    start: () => void;
+    /**
+     * Stop polling.
+     */
+    stop: () => void;
+    /**
+     * Manually trigger a poll.
+     */
+    poll: () => Promise<void>;
+    /**
+     * Reset the poller and clean up resources.
+     */
+    reset: () => void;
+    /**
+     * Subscribe to payment method events.
+     */
+    subscribe: (callback: (paymentMethod: SavedPaymentMethod) => void) => () => void;
+    /**
+     * Check if polling is currently active.
+     */
+    isPolling: () => boolean;
+}
+
+/**
+ * Creates a payment method poller with manual control over the polling lifecycle.
+ * 
+ * @param api - The API function to call the event endpoint.
+ * @param initialEventID - The initial event ID to begin polling from.
+ * @param options - Optional configuration for property and action filtering.
+ * @returns A controller object for managing the polling lifecycle.
+ */
+export const createPaymentMethodPoller = (
+    api: Api,
+    initialEventID: string,
+    options?: PollPaymentMethodsOptions
+): PaymentMethodPoller => {
+    const { propertyKey, action } = options || {};
+
+    // Import createEventManager inline to avoid export issues
+    const createEventManager = (api: Api, eventID: string) => {
+        interface EventResponse {
+            EventID: string;
+            More: 0 | 1;
+            [key: string]: any;
+        }
+
+        const listeners: Array<(result: EventResponse) => void> = [];
+        let stateEventID = eventID;
+
+        const subscribe = (listener: (result: EventResponse) => void) => {
+            listeners.push(listener);
+            return () => {
+                const index = listeners.indexOf(listener);
+                if (index !== -1) {
+                    listeners.splice(index, 1);
+                }
+            };
+        };
+
+        const setEventID = (eventID: string) => {
+            stateEventID = eventID;
+        };
+
+        const getEventID = () => {
+            return stateEventID;
+        };
+
+        const call = async () => {
+            const eventID = stateEventID;
+            if (!eventID) {
+                throw new Error('EventID undefined');
+            }
+
+            const result = await api<EventResponse>({
+                url: `core/v5/events/${eventID}`,
+                method: 'get',
+                silence: true,
+            });
+
+            // Notify listeners with the result
+            listeners.forEach((listener) => {
+                try {
+                    listener(result);
+                } catch (e) {
+                    // Ignore listener errors
+                }
+            });
+
+            setEventID(result.EventID);
+        };
+
+        const stop = () => {
+            // No-op for this simple implementation
+        };
+
+        const reset = () => {
+            stateEventID = eventID;
+            listeners.length = 0;
+        };
+
+        return {
+            setEventID,
+            getEventID,
+            start: () => {},
+            stop,
+            call,
+            reset,
+            subscribe,
+        };
+    };
+
+    let eventManager: any | undefined;
+    let unsubscribe: (() => void) | undefined;
+    let currentEventID = initialEventID;
+    let attempts = 0;
+    let isPollingActive = false;
+    let pollingInterval: ReturnType<typeof setTimeout> | undefined;
+
+    const getEventManager = () => {
+        if (!eventManager) {
+            eventManager = createEventManager(api, currentEventID);
+        }
+        return eventManager;
+    };
+
+    const doPoll = async (): Promise<void> => {
+        if (attempts >= maxPollingSteps) {
+            stop();
+            return;
+        }
+
+        attempts++;
+        const manager = getEventManager();
+
+        try {
+            await manager.call();
+            const newEventID = manager.getEventID();
+            if (newEventID) {
+                currentEventID = newEventID;
+            }
+
+            // Check if we should stop based on received events
+            // This is a simplified check - in practice, event handlers run asynchronously
+            if (attempts >= maxPollingSteps) {
+                stop();
+            }
+        } catch (error) {
+            // Log error but continue polling if attempts remain
+            if (attempts < maxPollingSteps) {
+                // Schedule next poll
+                pollingInterval = setTimeout(doPoll, interval);
+            }
+        }
+    };
+
+    const start = (): void => {
+        if (isPollingActive) {
+            return;
+        }
+
+        isPollingActive = true;
+        attempts = 0;
+
+        // Subscribe if filtering is requested
+        if (propertyKey && action !== undefined) {
+            unsubscribe = getEventManager().subscribe((event: any) => {
+                const events = event[propertyKey] as EventItemUpdate<SavedPaymentMethod, 'PaymentMethod'>[] | undefined;
+                if (events && Array.isArray(events)) {
+                    for (const eventItem of events) {
+                        // Only check for CREATE or UPDATE actions, as DELETE has no PaymentMethod
+                        if (eventItem.Action === action && eventItem.Action !== EVENT_ACTIONS.DELETE) {
+                            const paymentMethod = (eventItem as any).PaymentMethod as SavedPaymentMethod | undefined;
+                            if (paymentMethod) {
+                                // Expected event received, stop polling
+                                stop();
+                            }
+                        }
+                    }
+                }
+            });
+        }
+
+        // Start polling with interval
+        doPoll();
+        pollingInterval = setTimeout(doPoll, interval);
+    };
+
+    const stop = (): void => {
+        isPollingActive = false;
+
+        if (pollingInterval) {
+            clearTimeout(pollingInterval);
+            pollingInterval = undefined;
+        }
+
+        if (eventManager) {
+            eventManager.stop();
+            eventManager.reset();
+            eventManager = undefined;
+        }
+
+        if (unsubscribe) {
+            unsubscribe();
+            unsubscribe = undefined;
+        }
+    };
+
+    const poll = async (): Promise<void> => {
+        const manager = getEventManager();
+        try {
+            await manager.call();
+        } catch {
+            // Silently handle errors
+        }
+    };
+
+    const reset = (): void => {
+        stop();
+        currentEventID = initialEventID;
+        attempts = 0;
+    };
+
+    const subscribe = (callback: (paymentMethod: SavedPaymentMethod) => void): (() => void) => {
+        const manager = getEventManager();
+        return manager.subscribe((event: any) => {
+            const events = event[propertyKey || ''] as EventItemUpdate<SavedPaymentMethod, 'PaymentMethod'>[] | undefined;
+            if (events && Array.isArray(events)) {
+                for (const eventItem of events) {
+                    const paymentMethod = (eventItem as any).PaymentMethod as SavedPaymentMethod | undefined;
+                    if (paymentMethod) {
+                        callback(paymentMethod);
+                    }
+                }
+            }
+        });
+    };
+
+    const isPolling = (): boolean => {
+        return isPollingActive;
+    };
+
+    return {
+        start,
+        stop,
+        poll,
+        reset,
+        subscribe,
+        isPolling,
+    };
+};

