+import { describe, it, expect } from '@jest/globals';
+import { DropdownSizeUnit, getMaxSizeValue, getWidthValue, getHeightValue, getProp } from './utils';
+
+describe('Dropdown utils', () => {
+    describe('getMaxSizeValue', () => {
+        it('should return undefined for undefined input', () => {
+            expect(getMaxSizeValue(undefined)).toBeUndefined();
+        });
+
+        it('should return "initial" for Viewport unit', () => {
+            expect(getMaxSizeValue(DropdownSizeUnit.Viewport)).toBe('initial');
+        });
+
+        it('should return the unit string for custom values', () => {
+            expect(getMaxSizeValue('13em')).toBe('13em');
+            expect(getMaxSizeValue('15px')).toBe('15px');
+            expect(getMaxSizeValue('50%')).toBe('50%');
+            expect(getMaxSizeValue('100vh')).toBe('100vh');
+        });
+
+        it('should return undefined for non-viewport enum values', () => {
+            expect(getMaxSizeValue(DropdownSizeUnit.Anchor)).toBeUndefined();
+            expect(getMaxSizeValue(DropdownSizeUnit.Static)).toBeUndefined();
+            expect(getMaxSizeValue(DropdownSizeUnit.Dynamic)).toBeUndefined();
+        });
+
+        it('should return undefined for invalid string values', () => {
+            expect(getMaxSizeValue('invalid')).toBeUndefined();
+            expect(getMaxSizeValue('em')).toBeUndefined();
+        });
+    });
+
+    describe('getWidthValue', () => {
+        it('should return undefined for undefined input', () => {
+            const result = getWidthValue(undefined, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return anchor width for Anchor unit', () => {
+            const anchorRect = { width: 200, height: 100, x: 0, y: 0, top: 0, left: 0, bottom: 100, right: 200 } as DOMRect;
+            const result = getWidthValue(DropdownSizeUnit.Anchor, anchorRect, null);
+            expect(result).toBe('200px');
+        });
+
+        it('should return content width for Static unit', () => {
+            const contentRect = { width: 300, height: 150, x: 0, y: 0, top: 0, left: 0, bottom: 150, right: 300 } as DOMRect;
+            const result = getWidthValue(DropdownSizeUnit.Static, null, contentRect);
+            expect(result).toBe('300px');
+        });
+
+        it('should return custom unit string directly', () => {
+            expect(getWidthValue('13em', null, null)).toBe('13em');
+            expect(getWidthValue('15px', null, null)).toBe('15px');
+        });
+
+        it('should return undefined for Dynamic unit', () => {
+            const result = getWidthValue(DropdownSizeUnit.Dynamic, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return undefined for Viewport unit', () => {
+            const result = getWidthValue(DropdownSizeUnit.Viewport, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return undefined when anchor rect is missing for Anchor unit', () => {
+            const result = getWidthValue(DropdownSizeUnit.Anchor, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return undefined when content rect is missing for Static unit', () => {
+            const result = getWidthValue(DropdownSizeUnit.Static, null, null);
+            expect(result).toBeUndefined();
+        });
+    });
+
+    describe('getHeightValue', () => {
+        it('should return undefined for undefined input', () => {
+            const result = getHeightValue(undefined, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return content height for Static unit', () => {
+            const contentRect = { width: 300, height: 150, x: 0, y: 0, top: 0, left: 0, bottom: 150, right: 300 } as DOMRect;
+            const result = getHeightValue(DropdownSizeUnit.Static, null, contentRect);
+            expect(result).toBe('150px');
+        });
+
+        it('should return custom unit string directly', () => {
+            expect(getHeightValue('13em', null, null)).toBe('13em');
+            expect(getHeightValue('15px', null, null)).toBe('15px');
+        });
+
+        it('should return undefined for Anchor unit', () => {
+            const result = getHeightValue(DropdownSizeUnit.Anchor, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return undefined for Dynamic unit', () => {
+            const result = getHeightValue(DropdownSizeUnit.Dynamic, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return undefined for Viewport unit', () => {
+            const result = getHeightValue(DropdownSizeUnit.Viewport, null, null);
+            expect(result).toBeUndefined();
+        });
+
+        it('should return undefined when content rect is missing for Static unit', () => {
+            const result = getHeightValue(DropdownSizeUnit.Static, null, null);
+            expect(result).toBeUndefined();
+        });
+    });
+
+    describe('getProp', () => {
+        it('should return undefined for undefined value', () => {
+            expect(getProp('--width', undefined)).toBeUndefined();
+        });
+
+        it('should return undefined for empty string', () => {
+            expect(getProp('--width', '')).toBeUndefined();
+        });
+
+        it('should return CSS variable mapping for valid value', () => {
+            expect(getProp('--width', '20px')).toEqual({ '--width': '20px' });
+            expect(getProp('--height', '100vh')).toEqual({ '--height': '100vh' });
+            expect(getProp('--max-width', 'initial')).toEqual({ '--max-width': 'initial' });
+        });
+    });
+});
