+import { Unit } from './interface';
+
+/**
+ * Dropdown size unit values for standardized sizing behavior.
+ */
+export enum DropdownSizeUnit {
+    /**
+     * Use viewport dimensions for the dropdown.
+     */
+    Viewport = 'viewport',
+    /**
+     * Use the anchor element's dimensions.
+     */
+    Anchor = 'anchor',
+    /**
+     * Use the content's natural dimensions.
+     */
+    Static = 'static',
+    /**
+     * Use dynamic sizing based on available space.
+     */
+    Dynamic = 'dynamic',
+}
+
+/**
+ * Dropdown size configuration interface.
+ */
+export interface DropdownSize {
+    /**
+     * Width of the dropdown.
+     */
+    width?: Unit | DropdownSizeUnit;
+    /**
+     * Height of the dropdown.
+     */
+    height?: Unit | DropdownSizeUnit;
+    /**
+     * Maximum width of the dropdown.
+     */
+    maxWidth?: Unit | DropdownSizeUnit;
+    /**
+     * Maximum height of the dropdown.
+     */
+    maxHeight?: Unit | DropdownSizeUnit;
+}
+
+/**
+ * Resolves the max-size CSS value.
+ * Returns `'initial'` if value is `DropdownSizeUnit.Viewport`,
+ * returns the unit string unchanged if valid, or `undefined` if not provided.
+ *
+ * @param value - The max-size value to resolve (maxWidth or maxHeight)
+ * @returns The CSS value string or undefined
+ */
+export function getMaxSizeValue(
+    value: DropdownSize['maxWidth'] | Unit | undefined
+): string | undefined {
+    if (value === undefined) {
+        return undefined;
+    }
+
+    if (value === DropdownSizeUnit.Viewport) {
+        return 'initial';
+    }
+
+    // Check if it's a valid unit string (contains digits followed by unit)
+    if (typeof value === 'string' && /\d+(?:\.\d+)?(?:px|em|rem|%|vh|vw|vmin|vmax|pt|pc|in|cm|mm|ex|ch|fr)?/i.test(value)) {
+        return value;
+    }
+
+    // For enum values that are not Viewport, return undefined
+    if (typeof value === 'string' && Object.values(DropdownSizeUnit).includes(value as DropdownSizeUnit)) {
+        return undefined;
+    }
+
+    return undefined;
+}
+
+/**
+ * Resolves a dropdown width based on the provided size.
+ * Uses anchor width for `Anchor`, content width for `Static`,
+ * passes through custom unit values, or `undefined` for `Dynamic`/missing rects.
+ *
+ * @param width - The width value to resolve
+ * @param anchorRect - The anchor element's bounding rect
+ * @param contentRect - The content element's bounding rect
+ * @returns The CSS width value or undefined
+ */
+export function getWidthValue(
+    width: DropdownSize['width'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined {
+    if (width === undefined) {
+        return undefined;
+    }
+
+    // Handle unit strings directly (e.g., "13em", "15px")
+    if (typeof width === 'string' && !Object.values(DropdownSizeUnit).includes(width as DropdownSizeUnit)) {
+        return width;
+    }
+
+    switch (width) {
+        case DropdownSizeUnit.Anchor:
+            return anchorRect?.width !== undefined ? `${anchorRect.width}px` : undefined;
+        case DropdownSizeUnit.Static:
+            return contentRect?.width !== undefined ? `${contentRect.width}px` : undefined;
+        case DropdownSizeUnit.Dynamic:
+        case DropdownSizeUnit.Viewport:
+        default:
+            return undefined;
+    }
+}
+
+/**
+ * Resolves dropdown height.
+ * Uses content height for `Static`, passes through unit strings,
+ * or `undefined` for `Dynamic`/missing rects.
+ *
+ * @param height - The height value to resolve
+ * @param anchorRect - The anchor element's bounding rect
+ * @param contentRect - The content element's bounding rect
+ * @returns The CSS height value or undefined
+ */
+export function getHeightValue(
+    height: DropdownSize['height'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined {
+    if (height === undefined) {
+        return undefined;
+    }
+
+    // Handle unit strings directly (e.g., "13em", "15px")
+    if (typeof height === 'string' && !Object.values(DropdownSizeUnit).includes(height as DropdownSizeUnit)) {
+        return height;
+    }
+
+    switch (height) {
+        case DropdownSizeUnit.Static:
+            return contentRect?.height !== undefined ? `${contentRect.height}px` : undefined;
+        case DropdownSizeUnit.Anchor:
+        case DropdownSizeUnit.Dynamic:
+        case DropdownSizeUnit.Viewport:
+        default:
+            return undefined;
+    }
+}
+
+/**
+ * Produces a CSS variable mapping if a value is provided, otherwise returns `undefined`.
+ *
+ * @param prop - The CSS variable name (e.g., "--width")
+ * @param value - The CSS value to set
+ * @returns A record with the CSS variable mapping, or undefined if value is empty
+ */
+export function getProp(prop: string, value: string | undefined): Record<string, string> | undefined {
+    if (value === undefined || value === '') {
+        return undefined;
+    }
+    return { [prop]: value };
+}

