@@ -0,0 +1,130 @@
+import { addMonths, format, getUnixTime } from 'date-fns';
+
+import { getSubscriptionExpiryInfo } from '../helpers/subscription';
+import { Renew, type SubscriptionModel } from '../interfaces';
+
+import { subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';
+
+describe('getSubscriptionExpiryInfo', () => {
+    it('should return undefined for undefined subscription', () => {
+        const result = getSubscriptionExpiryInfo(undefined);
+        expect(result).toBeUndefined();
+    });
+
+    it('should return undefined for free subscription', () => {
+        // Free subscriptions don't have PeriodEnd and should return undefined
+        const result = getSubscriptionExpiryInfo({} as any);
+        expect(result).toBeUndefined();
+    });
+
+    it('should return expiry info for a subscription without upcoming', () => {
+        const futureDate = addMonths(new Date(), 2);
+        const subscription = {
+            ...subscriptionMock,
+            PeriodEnd: getUnixTime(futureDate),
+        };
+
+        const result = getSubscriptionExpiryInfo(subscription);
+
+        expect(result).toBeDefined();
+        expect(result?.endTimestamp).toBe(getUnixTime(futureDate));
+        expect(result?.subscriptionExpiresSoon).toBe(false);
+        expect(result?.renewDisabled).toBe(false);
+        expect(result?.renewEnabled).toBe(true);
+        expect(result?.planDisplayName).toBe('Proton Unlimited');
+    });
+
+    it('should return the current subscription end timestamp during cancellation context', () => {
+        // When cancellationContext is true, we should use the current subscription's PeriodEnd
+        // even if there's an UpcomingSubscription
+        const subscription = {
+            ...subscriptionMock,
+            PeriodEnd: getUnixTime(addMonths(new Date(), 2)),
+            UpcomingSubscription: upcomingSubscriptionMock,
+        };
+
+        const result = getSubscriptionExpiryInfo(subscription, { cancellationContext: true });
+
+        expect(result).toBeDefined();
+        expect(result?.endTimestamp).toBe(getUnixTime(addMonths(new Date(), 2)));
+        // Should NOT be the upcoming subscription's end timestamp
+        expect(result?.endTimestamp).not.toBe(upcomingSubscriptionMock.PeriodEnd);
+    });
+
+    it('should return the current subscription end timestamp when renew is disabled', () => {
+        const subscription = {
+            ...subscriptionMock,
+            Renew: Renew.Disabled,
+            PeriodEnd: getUnixTime(addMonths(new Date(), 2)),
+            UpcomingSubscription: upcomingSubscriptionMock,
+        };
+
+        const result = getSubscriptionExpiryInfo(subscription);
+
+        // When renew is disabled, we should use the current subscription's PeriodEnd
+        expect(result).toBeDefined();
+        expect(result?.endTimestamp).toBe(getUnixTime(addMonths(new Date(), 2)));
+        expect(result?.renewDisabled).toBe(true);
+        expect(result?.renewEnabled).toBe(false);
+    });
+
+    it('should consider upcoming subscription when not in cancellation context', () => {
+        // When cancellationContext is false (default), we should consider the upcoming subscription
+        const subscription = {
+            ...subscriptionMock,
+            PeriodEnd: getUnixTime(addMonths(new Date(), 2)),
+            UpcomingSubscription: upcomingSubscriptionMock,
+        };
+
+        const result = getSubscriptionExpiryInfo(subscription);
+
+        // Should return the upcoming subscription's end timestamp
+        expect(result).toBeDefined();
+        expect(result?.endTimestamp).toBe(upcomingSubscriptionMock.PeriodEnd);
+    });
+
+    it('should return the current subscription when there is no upcoming subscription', () => {
+        const subscription = {
+            ...subscriptionMock,
+            PeriodEnd: getUnixTime(addMonths(new Date(), 2)),
+        };
+
+        const result = getSubscriptionExpiryInfo(subscription);
+
+        expect(result).toBeDefined();
+        expect(result?.endTimestamp).toBe(getUnixTime(addMonths(new Date(), 2)));
+    });
+
+    it('should set subscriptionExpiresSoon to true when within 7 days', () => {
+        const oneWeekFromNow = addMonths(new Date(), 0); // Actually just a few days
+        const oneWeekFromNowPlus6Days = addMonths(oneWeekFromNow, 0);
+        const oneWeekFromNowPlus6DaysUnix = getUnixTime(oneWeekFromNowPlus6Days);
+
+        // We need a date within 7 days
+        const oneWeekFromNowDate = new Date();
+        oneWeekFromNowDate.setDate(oneWeekFromNowDate.getDate() + 5); // 5 days from now
+
+        const subscription = {
+            ...subscriptionMock,
+            PeriodEnd: getUnixTime(oneWeekFromNowDate),
+        };
+
+        const result = getSubscriptionExpiryInfo(subscription);
+
+        expect(result).toBeDefined();
+        expect(result?.subscriptionExpiresSoon).toBe(true);
+    });
+
+    it('should not set subscriptionExpiresSoon when more than 7 days away', () => {
+        const futureDate = addMonths(new Date(), 2);
+        const subscription = {
+            ...subscriptionMock,
+            PeriodEnd: getUnixTime(futureDate),
+        };
+
+        const result = getSubscriptionExpiryInfo(subscription);
+
+        expect(result).toBeDefined();
+        expect(result?.subscriptionExpiresSoon).toBe(false);
+    });
+});

